  str_homestory_N23dianying_90030101_136_dialog_content = "Derecha. Así que no eres tan estúpido como pareces.",
  str_homestory_N23dianying_90030101_137_dialog_content = "Lo hicimos. Justo ahora, aquí mismo, en realidad. Dijo que murió aquí porque el personal no pudo reparar el equipo a tiempo para salvarla.",
