  str_homestory_N23dianying_90030101_143_dialog_content = "Estaba tratando de abrir la puerta, pero algo salió mal, así que quedé atrapado en el medio y morí.",
  str_homestory_N23dianying_90030101_144_dialog_content = "Estaba tratando de abrir la puerta, pero algo salió mal, así que quedé atrapado en el medio y morí. Estúpido, ¿no?",
  str_homestory_N23dianying_90030101_145_dialog_content = "Uhm... Mis condolencias.",
