  str_homestory_N23dianying_90030101_151_dialog_content = "¿Qué quieres decir? ¿Los restos de la sala de escape?",
  str_homestory_N23dianying_90030101_152_dialog_content = "Eso es exactamente lo que parece. Este lugar ha estado cerrado por un tiempo.",
  str_homestory_N23dianying_90030101_153_dialog_content = "Piénsalo. Después de un accidente que mató a dos personas, no hay forma de que este lugar siga funcionando.",
  str_homestory_N23dianying_90030101_154_dialog_content = "Será mejor que te vayas a casa. Me voy a dormir ahora.",
  str_homestory_N23dianying_90030101_155_dialog_content = "Será mejor que te vayas a casa. Voy a averiguar cómo deshacerme de la Piedra Cazadora.",
  str_homestory_N23dianying_90030101_156_dialog_content = "Espera... ¿Qué estás diciendo? ¿Un fantasma necesita dormir?",
