  str_homestory_N23dianying_90030101_158_dialog_content = "¿Qué quiso decir con... ha sido cerrado?",
  str_homestory_N23dianying_90030101_159_dialog_content = "¿Cerrar? ¡Pero entramos aquí con nuestros boletos!",
  str_homestory_N23dianying_90030101_160_dialog_content = "En realidad, si realmente lo piensas... No había nadie allí para revisar nuestros boletos, y no vimos exactamente a nadie excepto al asesino de la motosierra.",
