  str_homestory_N23dianying_90030101_162_dialog_content = "¡Eso es lo que pensé!",
  str_homestory_N23dianying_90030101_163_dialog_content = "¿Pero nadie viene a rescatarnos? ¿Estamos realmente atrapados aquí...?",
  str_homestory_N23dianying_90030101_164_dialog_content = "Pero ese asesino con motosierra... Debe ser el bastón, ¿verdad?",
