  str_homestory_N23dianying_90030101_166_dialog_content = "¡Oye! ¡La luz se enciende y se apaga de nuevo! ¿La puerta sigue atascada?",
  str_homestory_N23dianying_90030101_167_dialog_content = "Esto se está haciendo viejo... ¡N-No tengo miedo en absoluto!",
  str_homestory_N23dianying_90030101_168_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
