  str_homestory_N23dianying_90030101_174_dialog_content = "¡Escuchame!",
  str_homestory_N23dianying_90030101_175_dialog_content = "El Señor del Vacío Sin Fin.",
  str_homestory_N23dianying_90030101_176_dialog_content = "El Conquistador del Terror y el Miedo.",
  str_homestory_N23dianying_90030101_177_dialog_content = "El Hijo del Vacío y el Caos.",
  str_homestory_N23dianying_90030101_178_dialog_content = "¡Johnny, el Gran Señor Demonio Culinario!",
  str_homestory_N23dianying_90030101_179_dialog_content = "¡Te sacrifico los gusanos de arena más deliciosos y frescos!",
  str_homestory_N23dianying_90030101_180_dialog_content = "¡Tu servidor te espera!",
  str_homestory_N23dianying_90030101_181_dialog_content = "...",
  str_homestory_N23dianying_90030101_182_dialog_content = "...",
  str_homestory_N23dianying_90030101_183_dialog_content = "Eso no es asunto mío...",
  str_homestory_N23dianying_90030101_184_dialog_content = "¡Director! ¡Obviamente hay algo mal con los accesorios!",
  str_homestory_N23dianying_90030101_185_dialog_content = "Tenemos mucho margen de mejora en términos de accesorios, ¿no crees? Cachero.",
  str_homestory_N23dianying_90030101_186_dialog_content = "¿Eh? ¿Encontrar que? ¿De qué estás hablando?",
  str_homestory_N23dianying_90030101_187_dialog_content = "Encuéntralo... Ve a buscar la verdad...",
  str_homestory_N23dianying_90030101_188_dialog_content = "¿No te acabo de decir? Encuéntralo... ¡Ve a buscar la verdad!",
  str_homestory_N23dianying_90030101_189_dialog_content = "¡Pero no hay nada en esa dirección!",
  str_homestory_N23dianying_90030101_190_dialog_content = "¿No? ¿Como es eso posible?",
  str_homestory_N23dianying_90030101_191_dialog_content = "¿No puedes verlo? Es donde la carne fue desgarrada y el alma devorada.",
  str_homestory_N23dianying_90030101_192_dialog_content = "El lugar donde pongo mis copias manuscritas del dogma.",
  str_homestory_N23dianying_90030101_193_dialog_content = "Creo que hay algo mal con los accesorios...",
  str_homestory_N23dianying_90030101_194_dialog_content = "¡Y, Nails, no estabas siguiendo tus líneas!",
  str_homestory_N23dianying_90030101_195_dialog_content = "Lo siento... Me disculparé y confesaré con uñas...",
  str_homestory_N23dianying_90030101_196_dialog_content = "¡Pará pará pará! ¡Esta no es una película de terror sangrienta! ¡Estropeará el conjunto también!",
  str_homestory_N23dianying_90030101_197_dialog_content = "Es tan difícil de imaginar...",
  str_homestory_N23dianying_90030101_198_dialog_content = "Ponle una tapa, ¿quieres? ¡Deja de avergonzar el nombre de True Order!",
  str_homestory_N23dianying_90030101_199_dialog_content = "¿De verdad no puedes verlo? ¡El equipo de utilería realmente dejó caer la pelota!",
  str_homestory_N23dianying_90030101_200_dialog_content = "¡Actuar con accesorios imaginarios es tan poco confiable!",
  str_homestory_N23dianying_90030101_201_dialog_content = "Todos los accesorios y decorados se sienten baratos. ¡Esta no es manera de hacer una película de calidad!",
  str_homestory_N23dianying_90030101_202_dialog_content = "Bueno, tienes un punto.",
  str_homestory_N23dianying_90030101_203_dialog_content = "Definitivamente hay algo mal, especialmente cuando incluso Brock piensa eso.",
  str_homestory_N23dianying_90030101_204_dialog_content = "¡Oye! ¿¡Qué se supone que significa eso!?",
  str_homestory_N23dianying_90030101_205_dialog_content = "De todos modos, será mejor que preparemos los accesorios y volvamos a filmar esto.",
  str_homestory_N23dianying_90030101_206_dialog_content = "Esta bien. Como protagonista femenina, soy paciente. Volveremos una vez que el set esté preparado.",
  str_homestory_N23dianying_90030201_1_dialog_content = "¿Es esta la parte más profunda de la legendaria Cueva del Dragón, el Salón de los Tesoros...?",
  str_homestory_N23dianying_90030201_2_dialog_content = "Bueno, ¡este tiene que ser el legendario Frost Mirror! ¡Puede responder cualquier pregunta que le hagas y tiene un poder mágico inagotable!",
  str_homestory_N23dianying_90030201_2X1_dialog_content = "Bueno, ¡el legendario Frost Mirror tiene que estar aquí! ¡Puede responder cualquier pregunta que le hagas y tiene un poder mágico inagotable!",
  str_homestory_N23dianying_90030201_3_dialog_content = "No tengo idea de adónde fue ese estúpido dragón guardián del espejo, pero conseguir esto fue pan comido.",
  str_homestory_N23dianying_90030201_3X1_dialog_content = "No tengo idea de adónde fue ese estúpido dragón guardián del espejo, pero colarse aquí fue pan comido.",
  str_homestory_N23dianying_90030201_4_dialog_content = "Siempre y cuando lo saquemos de aquí... Habrá un montón de gente rogando pagar un ojo de la cara por ello. ¡Quién sabe, el rey podría incluso concederme un título y algunas tierras!",
  str_homestory_N23dianying_90030201_4X1_dialog_content = "¡O simplemente podría usar su poder para hacer un montón de dinero! ¡Me uniría a la lista rica en poco tiempo!",
  str_homestory_N23dianying_90030201_5_dialog_content = "Jajaja... ¡Un tesoro tan raro finalmente está en manos de Barbatos, el comerciante criminal más grande de todos los tiempos!",
  str_homestory_N23dianying_90030201_6_dialog_content = "S-Así que... Ejem, así que me ayudaré a mí mismo.",
  str_homestory_N23dianying_90030201_6X1_dialog_content = "¿Cómo podrían equivocarse en sus líneas? Cachero.",
  str_homestory_N23dianying_90030201_6X2_dialog_content = "¡Tú puedes hacerlo, Revy!",
  str_homestory_N23dianying_90030201_6X3_dialog_content = "Su pago debería ser descontado por decir algo incorrecto, ¿verdad? Cachero.",
  str_homestory_N23dianying_90030201_7_dialog_content = "¿Vaya? Alguien se acerca. Pero, ¿cómo es que están en el Salón de los Tesoros...?",
  str_homestory_N23dianying_90030201_7X1_dialog_content = "¿Qué? Te juro que he buscado por todos lados, pero no hay nada que parezca un espejo mágico.",
  str_homestory_N23dianying_90030201_8_dialog_content = "Oh, olvídalo, no hay tiempo para eso. Primero me agacharé detrás del espejo.",
  str_homestory_N23dianying_90030201_8X1_dialog_content = "¿Seguramente nadie más podría haber robado ya el espejo...?",
  str_homestory_N23dianying_90030201_9_dialog_content = "¡Lo encontré! Lo encontré-!!",
  str_homestory_N23dianying_90030201_9X1_dialog_content = "¡Lo encontré! Lo encontré-!! ¡Esta debe ser la etapa final!",
  str_homestory_N23dianying_90030201_10_dialog_content = "Déjame echar un vistazo. Hm... Este hermoso árbol resplandeciente...",
  str_homestory_N23dianying_90030201_10X1_dialog_content = "¡Déjame echar un vistazo a este hermoso árbol resplandeciente!",
  str_homestory_N23dianying_90030201_11_dialog_content = "Hmm... Qué vanidosa estatua del Dragón de Escarcha.",
  str_homestory_N23dianying_90030201_11X1_dialog_content = "¡También está esta impresionante estatua del Dragón de Hielo!",
  str_homestory_N23dianying_90030201_14_dialog_content = "¡Excelente! Tomó mucho trabajo duro, ¡pero finalmente vencimos al Dragón de Escarcha y llegamos aquí!",
  str_homestory_N23dianying_90030201_14X1_dialog_content = "¡Excelente! Tomó mucho trabajo duro, ¡pero finalmente vencimos al Dragón de Escarcha y llegamos aquí! Entonces, ¿dónde está la recompensa suprema?",
  str_homestory_N23dianying_90030201_16_dialog_content = "Eh...? ¿Es este un muñeco de oso? ¿A los dragones de escarcha también les gustan este tipo de cosas?",
  str_homestory_N23dianying_90030201_16X1_dialog_content = "¿Qué es esto? ¿Un muñeco de oso? ¡Ajaja! ¿A los dragones de escarcha también les gustan este tipo de cosas?",
  str_homestory_N23dianying_90030201_17_dialog_content = "Realmente no puedo verlo...",
  str_homestory_N23dianying_90030201_17X1_dialog_content = "¡Simplemente no puedo verlo!",
  str_homestory_N23dianying_90030201_18_dialog_content = "Básicamente parece encajar con los rumores.",
  str_homestory_N23dianying_90030201_18X1_dialog_content = "Básicamente en línea con los rumores.",
  str_homestory_N23dianying_90030201_19_dialog_content = "Este lugar debería ser el Salón de los Tesoros, custodiado por el Dragón de Hielo.",
  str_homestory_N23dianying_90030201_19X1_dialog_content = "¡Este lugar debería ser el Salón de los Tesoros, custodiado por el Dragón de Hielo!",
  str_homestory_N23dianying_90030201_22_dialog_content = "¿Vaya? Qué es esto...? Parece un poco fuera de lugar.",
  str_homestory_N23dianying_90030201_22X1_dialog_content = "¿Vaya? ¿Qué es esto? Parece totalmente fuera de lugar.",
  str_homestory_N23dianying_90030201_23_dialog_content = "Aunque se dice que los dragones también coleccionan algunas cosas raras, supongo que es comprensible.",
  str_homestory_N23dianying_90030201_23X1_dialog_content = "Bueno, parece que los Dragones de Escarcha no son tan brillantes. Tal vez se ha extraviado.",
  str_homestory_N23dianying_90030201_27_dialog_content = "Déjame ver... Um, ¿no es esto un perchero?",
  str_homestory_N23dianying_90030201_27X1_dialog_content = "Déjame ver. ¿Eh? ¿Esto es un perchero?",
  str_homestory_N23dianying_90030201_28_dialog_content = "Y si miras la ropa que tiene puesta, ¿no te parece el tipo de ropa que podría llevar un personaje de un cuento de hadas?",
  str_homestory_N23dianying_90030201_28X1_dialog_content = "¿Y cómo es que hay ropa de niña en él? ¿Podría ser que el Dragón de Escarcha pueda transformarse en una niña?",
  str_homestory_N23dianying_90030201_37_dialog_content = "¿Es este realmente el Salón de los Tesoros?",
  str_homestory_N23dianying_90030201_37X1_dialog_content = "¿Es este realmente el Salón de los Tesoros? ¿No cometimos un error?",
  str_homestory_N23dianying_90030201_38_dialog_content = "¡Por supuesto que es! ¡¿No pasamos por todos esos problemas Y vencimos al Dragón de Hielo para llegar aquí?!",
  str_homestory_N23dianying_90030201_38X1_dialog_content = "¡Por supuesto que es! ¡¿No pasamos por todos esos problemas Y vencimos al Dragón de Hielo para llegar aquí?! ¡Además, el tutorial decía que también estaba aquí!",
  str_homestory_N23dianying_90030201_45_dialog_content = "Déjame ver. Hmmm, ¿hay un muñeco de nieve adorable?",
  str_homestory_N23dianying_90030201_45X1_dialog_content = "Déjame ver. ¿Eh? ¿Cómo es que hay un muñeco de nieve? Me recuerda a hacer uno con mis compañeros.",
  str_homestory_N23dianying_90030201_46_dialog_content = "No parece que se vaya a derretir. ¿El Dragón de Hielo lo hizo con su propio poder?",
  str_homestory_N23dianying_90030201_46X1_dialog_content = "No parece que se vaya a derretir. Muy impresionante.",
  str_homestory_N23dianying_90030201_63_dialog_content = "(¿Q-Qué...?! ¿Estos tipos realmente lograron vencer al Dragón de Escarcha? ¿El que dijo que podía derrotar a todo un ejército en un abrir y cerrar de ojos?)",
  str_homestory_N23dianying_90030201_63X1_dialog_content = "¡¿Eh?! ¿Que increible?",
  str_homestory_N23dianying_90030201_63X2_dialog_content = "Esto es algo poderoso, Chubb.",
  str_homestory_N23dianying_90030201_63X3_dialog_content = "No lo creo, Chubb.",
  str_homestory_N23dianying_90030201_64_dialog_content = "(¿Debería mostrarme...? Tal vez si explico que solo soy un ladrón o un comerciante o algo así, evitará que piensen que soy un enemigo si me descubren...)",
  str_homestory_N23dianying_90030201_65_dialog_content = "Sería terrible si me confunden con un monstruo y me persiguen...",
  str_homestory_N23dianying_90030201_66_dialog_content = "No tenía que ser tan difícil.",
  str_homestory_N23dianying_90030201_67_dialog_content = "Esto se debe a que confiaste ciegamente en alguien que conociste en el laberinto.",
  str_homestory_N23dianying_90030201_68_dialog_content = "Ese comerciante dijo que había encontrado un montón de equipo raro en la mazmorra, y simplemente te apresuraste a comerciar con él. ¡Pero todo es falso!",
  str_homestory_N23dianying_90030201_69_dialog_content = "Ese episodio nos puso en una posición financiera muy difícil.",
  str_homestory_N23dianying_90030201_69X1_dialog_content = "¡Ese episodio nos puso en una posición financiera muy difícil!",
  str_homestory_N23dianying_90030201_70_dialog_content = "Y ahora todo el mundo está fuera de trabajo. Incluso Miss Healer está ayudando a los heridos a traer algo de dinero.",
  str_homestory_N23dianying_90030201_71_dialog_content = "¿Eh? ¡Ay, no te preocupes por mí! Soy feliz tratando las heridas de los demás.",
  str_homestory_N23dianying_90030201_72_dialog_content = "Umm, uh... Eso fue solo un lapso momentáneo de juicio. ¡He sido mucho más cuidadoso desde entonces!",
  str_homestory_N23dianying_90030201_72X1_dialog_content = "Umm, uh... Eso fue solo un lapso momentáneo de juicio.",
  str_homestory_N23dianying_90030201_72X2_dialog_content = "No esperaba que un NPC de apariencia inofensiva fuera una amenaza.",
  str_homestory_N23dianying_90030201_73_dialog_content = "Eso no es ser más cuidadoso... Y después de eso vino el ladrón, quien afirmó poder ayudarnos a desarmar las trampas en la mazmorra.",
  str_homestory_N23dianying_90030201_73X1_dialog_content = "¿Ah, de verdad? Después de eso vino el ladrón, quien afirmó poder ayudarnos a desarmar las trampas en la mazmorra.",
  str_homestory_N23dianying_90030201_74_dialog_content = "¡¿Pero lo dejaste unirse a nosotros porque odias lidiar con trampas, solo para despertarte con todo el equipo perdido?!",
  str_homestory_N23dianying_90030201_74X1_dialog_content = "Lo dejaste unirse a nosotros porque odias lidiar con trampas, ¡solo para despertarte con todo el equipo desaparecido!",
  str_homestory_N23dianying_90030201_75_dialog_content = "Por suerte, todo era equipo normal. El equipo avanzado estaba en el herrero para reparaciones.",
  str_homestory_N23dianying_90030201_76_dialog_content = "De lo contrario, sería un verdadero dolor de cabeza tener que empezar de nuevo desde cero.",
  str_homestory_N23dianying_90030201_77_dialog_content = "¡Ya lo sabia! ¡No volveré a ser tan ingenuo!",
  str_homestory_N23dianying_90030201_77X1_dialog_content = "¡Ya lo sabia! ¡Una vez mordido dos veces tímido!",
  str_homestory_N23dianying_90030201_78_dialog_content = "Si alguna vez me encuentro con alguien que dice ser un ladrón, o un hombre de negocios, o básicamente alguien sospechoso, simplemente le daré un golpe allí mismo. Ahórrame un poco de molestia.",
  str_homestory_N23dianying_90030201_79_dialog_content = "Mmhmm, eso es más bien.",
  str_homestory_N23dianying_90030201_80_dialog_content = "(... Eso suena fatal si me muestro. Lo mejor es permanecer oculto.)",
  str_homestory_N23dianying_90030201_81_dialog_content = "Veamos primero cómo usar el espejo mágico. Me parece recordar la leyenda que decía que el espejo podía responder a cualquier pregunta.",
  str_homestory_N23dianying_90030201_82_dialog_content = "A mí me parece un espejo ordinario.",
  str_homestory_N23dianying_90030201_82X1_dialog_content = "A mí me parece un espejo ordinario. ¿Crees que hay un interruptor o algo así?",
  str_homestory_N23dianying_90030201_83_dialog_content = "Bueno, golpearlo no hizo nada. ¿Tienen alguna idea?",
  str_homestory_N23dianying_90030201_83X1_dialog_content = "¿Encontramos algún fragmento de diario con información relevante en el camino? ¿Qué estáis pensando chicos?",
  str_homestory_N23dianying_90030201_84_dialog_content = "¡Nada! Solo me interesa el tiro con arco.",
  str_homestory_N23dianying_90030201_84X1_dialog_content = "¡Nada! Solo me interesa el tiro con arco y los juegos de guerra.",
  str_homestory_N23dianying_90030201_85_dialog_content = "Aquí tampoco nada. Sólo me interesan las medidas terapéuticas. Otra magia me confunde.",
  str_homestory_N23dianying_90030201_85X1_dialog_content = "Aquí tampoco nada. Solo estoy interesado en la miel... Um, me refiero a los usos terapéuticos de la miel.",
  str_homestory_N23dianying_90030201_86_dialog_content = "¿No es esto una coincidencia? Resultó que solo me interesaba rebanar y trocear monstruos, pero justo ahora, mi interés se expandió para incluir rebanar y trocear a extraños sospechosos.",
  str_homestory_N23dianying_90030201_87_dialog_content = "(¿Eh? ¿Ninguno de ellos estudia magia?)",
  str_homestory_N23dianying_90030201_88_dialog_content = "(Esa podría ser mi oportunidad...)",
  str_homestory_N23dianying_90030201_89_dialog_content = "¡¿Eh?! ¿Alguien se esconde detrás del espejo mágico?",
  str_homestory_N23dianying_90030201_89X1_dialog_content = "¡¿Eh?! ¿Hay alguien detrás del espejo mágico? ¿Un enemigo oculto?",
  str_homestory_N23dianying_90030201_90_dialog_content = "¡Todos bienvenidos!",
  str_homestory_N23dianying_90030201_91_dialog_content = "Valientes exploradores.",
  str_homestory_N23dianying_90030201_92_dialog_content = "¿Quién eres? ¿Qué estás haciendo aquí?",
  str_homestory_N23dianying_90030201_92X1_dialog_content = "¿Quién eres? ¿Qué estás haciendo aquí? ¿Eres un enemigo o algún tipo de huevo de pascua?",
  str_homestory_N23dianying_90030201_93_dialog_content = "No hay necesidad de temer.",
  str_homestory_N23dianying_90030201_94_dialog_content = "No hay necesidad de preocuparse.",
  str_homestory_N23dianying_90030201_95_dialog_content = "Soy el espíritu que reside dentro de este objeto, el Genio del Espejo.",
  str_homestory_N23dianying_90030201_95X1_dialog_content = "¡Se está metiendo en eso! ¡Jajaja!",
  str_homestory_N23dianying_90030201_95X2_dialog_content = "¡Eso es vergonzoso, Chubb!",
  str_homestory_N23dianying_90030201_95X3_dialog_content = "Están realmente inmersos en su personaje, Chubb.",
  str_homestory_N23dianying_90030201_96_dialog_content = "Genio del espejo...? No creo haberte oído mencionar en ninguna de las leyendas.",
  str_homestory_N23dianying_90030201_97_dialog_content = "Muy bien, muy bien. Pero las leyendas son solo eso después de todo. No es como si alguien hubiera recuperado el Frost Mirror, ¿verdad?",
  str_homestory_N23dianying_90030201_97X1_dialog_content = "Muy bien, muy bien. Pero las leyendas son solo eso después de todo. No es como si alguien hubiera recuperado el Frost Mirror.",
  str_homestory_N23dianying_90030201_98_dialog_content = "Pero, ¿por qué está hablando de una manera tan divertida?",
  str_homestory_N23dianying_90030201_98X1_dialog_content = "El tono de este tipo es sospechoso, si me preguntas.",
  str_homestory_N23dianying_90030201_99_dialog_content = "Eso es, ah, eso es porque he estado encerrado aquí durante mucho tiempo, con poder mágico insuficiente.",
  str_homestory_N23dianying_90030201_100_dialog_content = "¡Te lo ruego, llévame lejos de aquí, lejos del Dragón de Hielo! Llévame a una tierra lejana y deshabitada.",
  str_homestory_N23dianying_90030201_101_dialog_content = "(Después de lo cual me escabulliré en la noche con mi espejo mágico. Jejeje...)",
  str_homestory_N23dianying_90030201_102_dialog_content = "¡Ah, claro! ¡Bueno, será mejor que nos vayamos!",
  str_homestory_N23dianying_90030201_103_dialog_content = "¡Espera un minuto! ¿Qué pasa con todo ese asunto de \"confiar en los demás con demasiada facilidad\"? ¡Al menos pídele su opinión a la señorita Healer primero!",
  str_homestory_N23dianying_90030201_104_dialog_content = "Un Genio real debería ser capaz de darnos una pequeña demostración del poder del espejo. Eso sería suficiente para probar sus afirmaciones.",
  str_homestory_N23dianying_90030201_104X1_dialog_content = "Déjame pensar... ¡Ay!",
  str_homestory_N23dianying_90030201_104X2_dialog_content = "¿Eh? ¿Qué es?",
  str_homestory_N23dianying_90030201_104X3_dialog_content = "Se me escapó el tiempo: ¡tenía que terminar una misión que me dio la reina! ¡Lo siento mucho, directora!",
  str_homestory_N23dianying_90030201_104X4_dialog_content = "Eh, es lo que es. Encontraremos un reemplazo.",
  str_homestory_N23dianying_90030201_105_dialog_content = "(... Esto era de esperar. Sin embargo, estoy preparado.)",
  str_homestory_N23dianying_90030201_106_dialog_content = "Pero por supuesto.",
  str_homestory_N23dianying_90030201_107_dialog_content = "Por favor, observe—",
  str_homestory_N23dianying_90030201_108_dialog_content = "¡Que haya luz!",
  str_homestory_N23dianying_90030201_109_dialog_content = "Espejo mágico.",
  str_homestory_N23dianying_90030201_110_dialog_content = "(Esos costosos pergaminos mágicos son útiles).",
  str_homestory_N23dianying_90030201_111_dialog_content = "¡Guau! ¡En realidad está respondiendo!",
  str_homestory_N23dianying_90030201_112_dialog_content = "Efectivamente, no puedes simplemente lanzarte como un \"Héroe\". Parece que necesita el Genio del Espejo para funcionar.",
  str_homestory_N23dianying_90030201_112X1_dialog_content = "Efectivamente, las conjeturas heroicas y salvajes no van a funcionar. Parece que necesitamos la ayuda del Genio del Espejo para usarlo.",
  str_homestory_N23dianying_90030201_113_dialog_content = "Ohhh... ¡Apuesto a que funcionará con un par de buenos golpes más!",
  str_homestory_N23dianying_90030201_113X1_dialog_content = "Ohhh... ¡Apuesto a que funcionará con un par de buenos golpes más! ¡Muchos juegos tienen este diseño!",
  str_homestory_N23dianying_90030201_114_dialog_content = "No estoy seguro de poder tratar un espejo mágico roto...",
  str_homestory_N23dianying_90030201_115_dialog_content = "¡No importa eso por ahora! ¡Continúa y prueba sus habilidades para responder preguntas!",
  str_homestory_N23dianying_90030201_116_dialog_content = "¡Acérquese, señorita Healer!",
  str_homestory_N23dianying_90030201_117_dialog_content = "¡De acuerdo! Oh, Espejo Mágico, Espejo Mágico... ¿Cuál será el pináculo de mis logros curativos?",
  str_homestory_N23dianying_90030201_118_dialog_content = "Esa es la forma de preguntar, ¿no?",
  str_homestory_N23dianying_90030201_119_dialog_content = "Un momento-",
  str_homestory_N23dianying_90030201_120_dialog_content = "La respuesta está surgiendo.",
  str_homestory_N23dianying_90030201_121_dialog_content = "Ganarás fama y fortuna por el trato que le des a un laird, caído en un sueño a causa de su enfermedad.",
  str_homestory_N23dianying_90030201_122_dialog_content = "Pero tu hazaña más grande y final será curar al Rey Demonio de la narcolepsia y dotarlo de energía infinita.",
  str_homestory_N23dianying_90030201_123_dialog_content = "Esto tiene el desafortunado efecto secundario de hacer que permanezca eternamente despierto, y en su furia y exceso de poder, destruye el mundo entero.",
  str_homestory_N23dianying_90030201_123X1_dialog_content = "Adelante, sigue inventando cosas.",
  str_homestory_N23dianying_90030201_123X2_dialog_content = "¿Están improvisando? Cachero.",
  str_homestory_N23dianying_90030201_123X3_dialog_content = "¡Nadie va a creer eso, Chubb!",
  str_homestory_N23dianying_90030201_124_dialog_content = "...",
  str_homestory_N23dianying_90030201_125_dialog_content = "E-El Espejo Mágico no siempre es totalmente preciso, ¿verdad? No hay necesidad de creer cada palabra.",
  str_homestory_N23dianying_90030201_126_dialog_content = "En realidad soy... ¿soy lo suficientemente poderoso como para despertar al Rey Demonio?",
  str_homestory_N23dianying_90030201_127_dialog_content = "Jejeje...",
  str_homestory_N23dianying_90030201_128_dialog_content = "¡No es divertido, señorita Healer! Usted me está volviendo loco.",
  str_homestory_N23dianying_90030201_129_dialog_content = "¡No te preocupes por mí! ¡El turno del arquero!",
  str_homestory_N23dianying_90030201_130_dialog_content = "Meh, no estoy molesto. Ni siquiera estoy interesado en todas estas cosas.",
  str_homestory_N23dianying_90030201_131_dialog_content = "Deja que el Héroe sea el siguiente.",
  str_homestory_N23dianying_90030201_132_dialog_content = "¡Por supuesto! Espejo Mágico, Espejo Mágico, ¡dime ahora cuán poderoso seré!",
  str_homestory_N23dianying_90030201_133_dialog_content = "Tú... Abandonarás tu título de Héroe de la Luz y te enamorarás de las pequeñas criaturas que encuentres en tus aventuras.",
  str_homestory_N23dianying_90030201_133X1_dialog_content = "Tú... Abandonarás tu título como el Héroe de la Luz y comenzarás a estudiar \"Magimechs\", un tipo de robot gigante.",
  str_homestory_N23dianying_90030201_134_dialog_content = "Luego trabajarás con ellos para derribar a todos tus enemigos líderes de gimnasio, uno por uno.",
  str_homestory_N23dianying_90030201_134X1_dialog_content = "Pero esos robots, inicialmente creados para proteger a las personas, se vuelven conscientes de sí mismos y comienzan a atacar a las personas en su lugar.",
  str_homestory_N23dianying_90030201_135_dialog_content = "Pero tú... nunca te convertirás en Campeón, y eventualmente perecerás en una ignominia abatida.",
  str_homestory_N23dianying_90030201_135X1_dialog_content = "Y te embarcarás en una misión con tu único amigo robot para descubrir la verdad detrás de la insurrección de Magimech.",
  str_homestory_N23dianying_90030201_135A1_dialog_content = "Cada vez es más ridículo, Chubb.",
  str_homestory_N23dianying_90030201_135A2_dialog_content = "¿Eso suena familiar?",
  str_homestory_N23dianying_90030201_135A3_dialog_content = "¿Es inexplicablemente atractivo?",
  str_homestory_N23dianying_90030201_136_dialog_content = "¿Cuáles son las posibilidades...",
  str_homestory_N23dianying_90030201_137_dialog_content = "¡Espejo mágico sin sentido! ¡Cómo te atreves a calumniar así a mi amado Héroe!",
  str_homestory_N23dianying_90030201_137X1_dialog_content = "¡Sigues diciendo tonterías, Mirror! ¡¡Cómo te atreves a calumniar así a nuestro poderoso Héroe!!",
  str_homestory_N23dianying_90030201_138_dialog_content = "¿Eh? ¡Esperar! ¡Espera un minuto!",
  str_homestory_N23dianying_90030201_139_dialog_content = "¡Así que ESA es tu relación—!",
  str_homestory_N23dianying_90030201_139X1_dialog_content = "¡Relajarse!",
  str_homestory_N23dianying_90030201_140_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  str_homestory_N23dianying_90030201_141_dialog_content = "Oye, ¿qué estás haciendo? Si dañas el Espejo Mágico, el Genio podría resultar herido o incluso morir.",
  str_homestory_N23dianying_90030201_142_dialog_content = "¡Mira su expresión de dolor!",
  str_homestory_N23dianying_90030201_143_dialog_content = "Dolor... ¿expresión?",
  str_homestory_N23dianying_90030201_144_option_content = "Colapsar",
  str_homestory_N23dianying_90030201_145_dialog_content = "¡Caída, Barbatos! \"¡Haz un ruido de dolor y colapsa!\"",
  str_homestory_N23dianying_90030201_146_dialog_content = "Oh...",
  str_homestory_N23dianying_90030201_147_dialog_content = "... ¡Vaya! ¡Qué agonía!",
  str_homestory_N23dianying_90030201_148_dialog_content = "Estoy herido-",
  str_homestory_N23dianying_90030201_149_dialog_content = "Lo siento... Fui demasiado impulsivo...",
  str_homestory_N23dianying_90030201_149X1_dialog_content = "Lo siento... Estas son las locuras de la juventud.",
  str_homestory_N23dianying_90030201_150_dialog_content = "¿Puedo molestarla para que lo intente, señorita Healer?",
  str_homestory_N23dianying_90030201_151_dialog_content = "Le daré una oportunidad... ¡Aunque solo sea para remover un poco la olla! ¡Soy, después de todo, el que puede tratar a un rey demonio!",
  str_homestory_N23dianying_90030201_152_dialog_content = "No dejarás que nadie lo olvide pronto, ¿verdad?",
  str_homestory_N23dianying_90030201_153_dialog_content = "Hmm, claramente es el Espejo Mágico, pero ¿cómo es que se daña tan fácilmente?",
  str_homestory_N23dianying_90030201_154_dialog_content = "Artesanía de mala calidad.",
  str_homestory_N23dianying_90030201_155_dialog_content = "Siento poder curativo.",
  str_homestory_N23dianying_90030201_156_dialog_content = "¡Yo, el Genio del Espejo, estoy restaurado!",
  str_homestory_N23dianying_90030201_157_dialog_content = "¡Excelente! Y, eh, nuestras disculpas.",
  str_homestory_N23dianying_90030201_157X1_dialog_content = "¡Excelente! Y, eh, lo siento por eso.",
  str_homestory_N23dianying_90030201_158_dialog_content = "A veces, el Arquero es incluso más impetuoso que yo. Pero aparte de este pequeño defecto, tiene un buen corazón.",
  str_homestory_N23dianying_90030201_159_dialog_content = "¿Desde cuando ustedes dos...",
  str_homestory_N23dianying_90030201_160_dialog_content = "Jajajajaja—",
  str_homestory_N23dianying_90030201_161_dialog_content = "¡¿Eso viene de afuera?!",
  str_homestory_N23dianying_90030201_162_dialog_content = "¡Es el Dragón de Hielo!",
  str_homestory_N23dianying_90030201_163_dialog_content = "¡Imbéciles! ¿De verdad pensaste que podrías matarme?",
  str_homestory_N23dianying_90030201_164_dialog_content = "Has perdido la oportunidad de derrotarme y ahora me voy, ¡y me llevo el Frost Mirror!",
  str_homestory_N23dianying_90030201_165_dialog_content = "¡Lamentad vuestra estupidez por el resto de vuestras vidas! Jajajaja—",
  str_homestory_N23dianying_90030201_166_dialog_content = "...",
  str_homestory_N23dianying_90030201_167_dialog_content = "...",
  str_homestory_N23dianying_90030201_168_dialog_content = "...",
  str_homestory_N23dianying_90030201_169_dialog_content = "¿Qué estaba diciendo ese dragón tonto?",
  str_homestory_N23dianying_90030201_170_dialog_content = "No se dio cuenta de que ahora tenemos el Frost Mirror.",
  str_homestory_N23dianying_90030201_170X1_dialog_content = "¡Qué gran bufón! ¡Tenemos el Frost Mirror, jajaja!",
  str_homestory_N23dianying_90030201_171_dialog_content = "Pero ahora que sabemos que el Dragón de Hielo está tras el Espejo, tenemos que estar en guardia y vigilarlo en todo momento.",
  str_homestory_N23dianying_90030201_172_dialog_content = "No te preocupes. Te protegeremos.",
  str_homestory_N23dianying_90030201_173_dialog_content = "... Sí Sí. Multa. Tienes toda la razón.",
  str_homestory_N23dianying_90030201_174_dialog_content = "De verdad, te lo agradezco mucho.",
  str_homestory_N23dianying_90030201_175_option_content = "Siente que algo no está del todo bien",
  str_homestory_N23dianying_90030201_176_dialog_content = "Archer, de repente sientes que algo anda mal. \"Este tipo es realmente sospechoso\".",
  str_homestory_N23dianying_90030201_177_dialog_content = "A pesar de que el espejo, donde supuestamente vives, fue claramente atacado, no pareciste reaccionar. ¿No es extraño?",
  str_homestory_N23dianying_90030201_177X1_dialog_content = "A pesar de que el espejo, donde supuestamente vives, fue claramente atacado, no pareciste reaccionar. Eso es bastante extraño.",
  str_homestory_N23dianying_90030201_178_dialog_content = "¿Qué? ¿Estás diciendo que este tipo...",
  str_homestory_N23dianying_90030201_178X1_dialog_content = "¿Qué? Quieres decir, ¿estás diciendo que este tipo no es ningún tipo de huevo de Pascua en absoluto?",
  str_homestory_N23dianying_90030201_179_dialog_content = "¡Espera, espera un momento! Puedo explicarlo: me duele, ¡tanto dolor que creo que me voy a desmayar!",
  str_homestory_N23dianying_90030201_180_dialog_content = "¡Puedo explicarlo! Por favor, solo escucha.",
  str_homestory_N23dianying_90030201_181_dialog_content = "Jajajajaja—",
  str_homestory_N23dianying_90030201_182_dialog_content = "¡¿Eso viene de afuera?!",
  str_homestory_N23dianying_90030201_183_dialog_content = "¡Es el Dragón de Hielo!",
  str_homestory_N23dianying_90030201_184_dialog_content = "¡Imbéciles! ¿De verdad pensaste que podrías matarme?",
  str_homestory_N23dianying_90030201_185_dialog_content = "Has perdido la oportunidad de derrotarme y ahora me voy, ¡y me llevo el Frost Mirror!",
  str_homestory_N23dianying_90030201_186_dialog_content = "¡Lamentad vuestra estupidez por el resto de vuestras vidas! Jajajaja—",
  str_homestory_N23dianying_90030201_187_dialog_content = "Sin perdón-",
  str_homestory_N23dianying_90030201_188_option_content = "Realización repentina",
  str_homestory_N23dianying_90030201_189_dialog_content = "Héroe, de repente te das cuenta de algo vital. \"La espada se ha ido\".",
  str_homestory_N23dianying_90030201_190_dialog_content = "Espera, olvídate de eso por un segundo. ¿Soy yo o falta la espada?",
  str_homestory_N23dianying_90030201_191_dialog_content = "De ninguna manera... No puede seguir atascado en la cabeza del Dragón de Escarcha, ¿verdad?",
  str_homestory_N23dianying_90030201_192_dialog_content = "¡Rápido, regresemos y busquemos! ¡Estamos en un gran problema si Hero pierde la espada!",
  str_homestory_N23dianying_90030201_193_dialog_content = "¿Vaya? Erm... ¿Ven de nuevo?",
  str_homestory_N23dianying_90030201_194_dialog_content = "¿Eh? ¿Quién es éste?",
  str_homestory_N23dianying_90030201_194X1_dialog_content = "¿Eh? ¿Quién es éste? ¿Un PNJ de fondo?",
  str_homestory_N23dianying_90030201_195_dialog_content = "Olvídate de ella. Tenemos que buscar el espejo.",
  str_homestory_N23dianying_90030201_195X1_dialog_content = "Olvídate de ella. Tenemos que buscar el espejo. Todavía tengo cosas que tengo que hacer después.",
  str_homestory_N23dianying_90030201_196_dialog_content = "¿Mmm?",
  str_homestory_N23dianying_90030201_197_dialog_content = "¿Qué?",
  str_homestory_N23dianying_90030201_198_dialog_content = "¿Cómo es que no hay señales del Espejo Mágico?",
  str_homestory_N23dianying_90030201_198X1_dialog_content = "¿Cómo es que no hay señales del Espejo Mágico? ¿Todavía no hemos marcado alguna casilla arbitraria?",
  str_homestory_N23dianying_90030201_199_dialog_content = "¿Crees que este tipo lo robó?",
  str_homestory_N23dianying_90030201_200_dialog_content = "¡¿Qué?! Estaba a punto de preguntarte eso.",
  str_homestory_N23dianying_90030201_201_dialog_content = "No fue divertido colarme aquí, y tenía que tener ese espejo para convertirme en el comerciante más rico del mundo.",
  str_homestory_N23dianying_90030201_202_dialog_content = "¿Furtivamente en? No supongas, ¿es este tipo algún tipo de ladrón?",
  str_homestory_N23dianying_90030201_203_dialog_content = "Eso es realmente bastante desencadenante.",
  str_homestory_N23dianying_90030201_203X1_dialog_content = "Eso me trae algunos recuerdos realmente desagradables. Tengo que darte una lección.",
  str_homestory_N23dianying_90030201_204_dialog_content = "Jajajajaja—",
  str_homestory_N23dianying_90030201_205_dialog_content = "¡¿Eso viene de afuera?!",
  str_homestory_N23dianying_90030201_206_dialog_content = "¡Es el Dragón de Hielo!",
  str_homestory_N23dianying_90030201_207_dialog_content = "¡Imbéciles! ¿De verdad pensaste que podrías vencerme?",
  str_homestory_N23dianying_90030201_208_dialog_content = "Ahora, me voy, ¡y me llevo el Frost Mirror conmigo! Otra cosa... Este lugar se derrumbará en cualquier momento, ¡así que lamenten su estupidez por el resto de sus cortas vidas! Jajajaja—",
  str_homestory_N23dianying_90030201_209_dialog_content = "Diablos, el dragón se escapó.",
  str_homestory_N23dianying_90030201_210_dialog_content = "¡Ve tras él, ahora!",
  str_homestory_N23dianying_90030201_210X1_dialog_content = "¡Dense prisa, todos! ¡Yo, eh, voy a terminar una misión que me dio la reina!",
  str_homestory_N23dianying_90030201_211_dialog_content = "¿Oh? ¡Oye! ¡Espérame!",
  str_homestory_N23dianying_90030201_211X1_dialog_content = "¡Este final es demasiado chapucero! ¡Cachero!",
  str_homestory_N23dianying_90030201_212_dialog_content = "No puedo decir si es solo tu naturaleza soberbia o tu actuación fenomenal, pero colapsar así fue un golpe de genialidad, Chubb.",
  str_homestory_N23dianying_90030201_213_dialog_content = "Heyyyy, ¿solo sentir que algo no está bien ahora? ¡Eso es un giro de trama un poco abrupto, Chubb!",
  str_homestory_N23dianying_90030201_214_dialog_content = "¿Por qué no lo explicas? ¡Continuar!",
  str_homestory_N23dianying_90030201_215_dialog_content = "Bueno, en la mayoría de las películas y programas de televisión, cuanto más quieres saber, más aumentan el suspenso, Chubb.",
  str_homestory_N23dianying_90030201_216_dialog_content = "¡Es muy posible que el Dragón de Hielo ya se haya ido volando con él!",
  str_homestory_N23dianying_90030201_217_dialog_content = "Pero la espada ni siquiera es un accesorio, ¿verdad? Entonces, ¿qué está pasando con la trama, Chubb?",
  str_homestory_N23dianying_90030301_1_dialog_content = "¡Uf! Puede que haya tomado dos días, pero al menos todo está saliendo bien.",
  str_homestory_N23dianying_90030301_2_dialog_content = "Esos matones están locos, destruyendo un lugar tan artístico.",
  str_homestory_N23dianying_90030301_3_dialog_content = "Pero afortunadamente, el piano escapó relativamente ileso...",
  str_homestory_N23dianying_90030301_3X1_dialog_content = "Parece caro, Chubb.",
  str_homestory_N23dianying_90030301_4_dialog_content = "Pero afortunadamente, esta también fue la oportunidad de persuadir al jefe para que cambiara el piano por un escenario.",
  str_homestory_N23dianying_90030301_5_dialog_content = "Después de eso, puedo cantar al contenido de mi corazón...",
  str_homestory_N23dianying_90030301_5X1_dialog_content = "Quiero bajar el volumen, Chubb...",
  str_homestory_N23dianying_90030301_6_dialog_content = "No puedo creer que el jefe sea tan tacaño.",
  str_homestory_N23dianying_90030301_7_dialog_content = "No está dispuesto a pagar las reparaciones del piano después de que se dañó.",
  str_homestory_N23dianying_90030301_8_dialog_content = "Y enviándome al viejo almacén por algunas decoraciones antiguas...",
  str_homestory_N23dianying_90030301_8X1_dialog_content = "¿Qué es esta cosa?",
  str_homestory_N23dianying_90030301_9_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  str_homestory_N23dianying_90030301_10_dialog_content = "Lo siento, pero estamos cerrados—",
  str_homestory_N23dianying_90030301_11_dialog_content = "¿Eh? ¡¿Tú otra vez?!",
  str_homestory_N23dianying_90030301_12_dialog_content = "Ahora ahora. Esa no es manera de dar la bienvenida a los clientes, Sr. Cantinero.",
  str_homestory_N23dianying_90030301_12X1_dialog_content = "Nos encontramos de nuevo, chico camarero.",
  str_homestory_N23dianying_90030301_13_dialog_content = "Tengo algunos asuntos urgentes que discutir con un viejo amigo hoy, así que dos copas de Umbraton Encounter, si es tan amable.",
  str_homestory_N23dianying_90030301_13X1_dialog_content = "He traído a un viejo amigo para hablar de negocios hoy, así que dos copas de Rediesel Special, por favor.",
  str_homestory_N23dianying_90030301_14_dialog_content = "Recién salido. Lo siento.",
  str_homestory_N23dianying_90030301_15_dialog_content = "¡Puedes agradecer a tus lacayos locos por eso, viniendo aquí hace un par de días y destrozando el lugar!",
  str_homestory_N23dianying_90030301_16_dialog_content = "Oh, eso es una vergüenza. Parece que no podré ofrecerle una bebida en esta ocasión.",
  str_homestory_N23dianying_90030301_16X1_dialog_content = "Oh, es cierto. Hubo ese... incidente.",
  str_homestory_N23dianying_90030301_17_dialog_content = "¡Estabas allí cuando sucedió! ¡No te hagas el inocente conmigo!",
  str_homestory_N23dianying_90030301_17X1_dialog_content = "¿Probamos en otro lugar?",
  str_homestory_N23dianying_90030301_18_dialog_content = "Está bien. De todos modos, sólo vamos a repasar el contrato. Hagámoslo.",
  str_homestory_N23dianying_90030301_19_dialog_content = "Por cierto, ¿podrías pedirle al cantinero que cambie la música a algo un poco más... refinado?",
  str_homestory_N23dianying_90030301_20_dialog_content = "Tu elección de música deja mucho que desear.",
  str_homestory_N23dianying_90030301_21_dialog_content = "¡¿Qué dijiste?!",
  str_homestory_N23dianying_90030301_22_dialog_content = "Todo este lugar necesita un cambio de imagen, en realidad.",
  str_homestory_N23dianying_90030301_23_dialog_content = "¡¿Qué dijiste?!",
  str_homestory_N23dianying_90030301_24_dialog_content = "Tengo a tus muchachos peleando aquí para agradecerles por eso también.",
  str_homestory_N23dianying_90030301_25_dialog_content = "¡Arruinó todas las decoraciones anteriores e incluso rompió los muebles!",
  str_homestory_N23dianying_90030301_26_dialog_content = "Multa. Déjame volver a hablar contigo sobre eso un poco más tarde.",
  str_homestory_N23dianying_90030301_27_dialog_content = "La decoración aquí es un poco... Bueno, es bastante mala.",
  str_homestory_N23dianying_90030301_28_dialog_content = "No quiero quedarme aquí ni un segundo más de lo absolutamente necesario.",
  str_homestory_N23dianying_90030301_29_dialog_content = "Pídele al cantinero que cambie el registro, por favor.",
  str_homestory_N23dianying_90030301_29X1_dialog_content = "¡Jajaja! Por favor, no te preocupes, amigo mío. Así es como habla.",
  str_homestory_N23dianying_90030301_30_dialog_content = "Aquí también somos buenos amigos del jefe. Estoy seguro de que no le importará.",
  str_homestory_N23dianying_90030301_30X1_dialog_content = "Soy buen amigo de tu jefe. No dirá nada si ocupo un poco de espacio aquí.",
  str_homestory_N23dianying_90030301_30X2_dialog_content = "Se lo explicaré todo más tarde. Simplemente salta y cambia la música.",
  str_homestory_N23dianying_90030301_31_dialog_content = "Eh... ¿Jefe?",
  str_homestory_N23dianying_90030301_32_dialog_content = "... Multa. Lo tengo.",
  str_homestory_N23dianying_90030301_33_dialog_content = "Drat. Usar a mi propio jefe para amenazarme.",
  str_homestory_N23dianying_90030301_34_dialog_content = "Este lugar no será más que un lugar frecuentado por pandillas a este ritmo.",
  str_homestory_N23dianying_90030301_35_dialog_content = "Tengo que pensar en una forma de evitar que vuelvan.",
  str_homestory_N23dianying_90030301_36_dialog_content = "¡Lo sé! En vista de que a este caballero tan elegante le gusta su entorno enrarecido, solo tengo el registro:",
  str_homestory_N23dianying_90030301_37_dialog_content = "Lo siento, esto no es lo que acordamos. No puedo-",
  str_homestory_N23dianying_90030301_38_dialog_content = "¿Eh? ¿Qué le pasa al cantinero? Esta musica-",
  str_homestory_N23dianying_90030301_38X1_dialog_content = "Estoy entusiasmado, Chubb.",
  str_homestory_N23dianying_90030301_39_dialog_content = "Haré que lo apague.",
  str_homestory_N23dianying_90030301_39X1_dialog_content = "Wow, el niño realmente jugó algo que me gusta.",
  str_homestory_N23dianying_90030301_39X2_dialog_content = "Pero puede ser un poco ruidoso para ti. Haré que lo apague.",
  str_homestory_N23dianying_90030301_40_dialog_content = "Está bien.",
  str_homestory_N23dianying_90030301_41_dialog_content = "La melodía y el ritmo... Esto me recuerda cuando solíamos tocar juntos en la gira.",
  str_homestory_N23dianying_90030301_42_dialog_content = "¿Nos dirigimos a un flashback, Chubb?",
  str_homestory_N23dianying_90030301_43_dialog_content = "Así que recuerdas esos días.",
  str_homestory_N23dianying_90030301_44_dialog_content = "Sé que nuestros caminos se separaron con el tiempo, ya que asumimos diferentes responsabilidades.",
  str_homestory_N23dianying_90030301_45_dialog_content = "Aunque entiendo nuestras diferentes posiciones, todavía me emociono a veces.",
  str_homestory_N23dianying_90030301_46_dialog_content = "Yo también.",
  str_homestory_N23dianying_90030301_47_dialog_content = "... ¿Sabes que? Permítanme regresar e intentar que las cosas avancen con el contrato.",
  str_homestory_N23dianying_90030301_47X1_dialog_content = "... Y las veces que sus Llaves Rediesel robaron nuestro cargamento.",
  str_homestory_N23dianying_90030301_47X2_dialog_content = "¡No olvidemos la vez que el Señor de las Sombras me envió tras de ti, y yo te perseguí a través del desierto de Reddiesel durante tres días completos y tres noches!",
  str_homestory_N23dianying_90030301_47X3_dialog_content = "¡Hey vamos! ¿No estamos destinados a hacer una película? ¿Qué pasa con la seriedad de repente?",
  str_homestory_N23dianying_90030301_47X4_dialog_content = "... Lo siento. Solo veo rojo cada vez que tengo que mirar su rostro.",
  str_homestory_N23dianying_90030301_47X5_dialog_content = "¿Dónde está el guión?",
  str_homestory_N23dianying_90030301_47X6_dialog_content = "¡¿Por qué no se cortó esta parte, Chubb?!",
  str_homestory_N23dianying_90030301_47X7_dialog_content = "Oh, sí, entonces, ¿qué tal si vuelvo y trato de hacer que las cosas avancen con el contrato?",
  str_homestory_N23dianying_90030301_48_dialog_content = "Véalo como ayudar a un viejo amigo.",
  str_homestory_N23dianying_90030301_49_dialog_content = "¿Así de fácil, Chubb?",
  str_homestory_N23dianying_90030301_50_dialog_content = "Bueno, realmente estoy agradecido.",
  str_homestory_N23dianying_90030301_51_dialog_content = "¡Vaya, nunca supe que fueras tan experto en leer la habitación! ¡Tenemos que darle las gracias por el éxito de estas negociaciones!",
  str_homestory_N23dianying_90030301_52_dialog_content = "Debes haber sabido acerca de nuestra antigua banda, los Rockin' Dragons, antes de elegir ese disco, ¿verdad?",
  str_homestory_N23dianying_90030301_52X1_dialog_content = "¿Ah, de verdad? ¡Muchas gracias!",
  str_homestory_N23dianying_90030301_52X2_dialog_content = "¡Vaya, nunca supe que fueras tan experto en leer la habitación! ¡Tenemos que darle las gracias por el éxito de estas negociaciones!",
  str_homestory_N23dianying_90030301_52X3_dialog_content = "Debes haber sabido acerca de nuestra antigua banda, los Rockin' Dragons, antes de elegir ese disco, ¿verdad?",
  str_homestory_N23dianying_90030301_53_dialog_content = "Chu! ¡Qué gran malentendido, Chubb!",
  str_homestory_N23dianying_90030301_54_dialog_content = "No soy-",
  str_homestory_N23dianying_90030301_55_dialog_content = "En vista de que el cantinero ha demostrado ser tan confiable, ¿puedo hacer otra solicitud?",
  str_homestory_N23dianying_90030301_56_dialog_content = "Tengo aquí un mensaje muy confidencial y extremadamente importante. Más tarde vendrá un intermediario a recogerlo.",
  str_homestory_N23dianying_90030301_56X1_dialog_content = "Bueno, es obvio por qué el jefe te eligió para administrar este lugar. ¡Buen trabajo!",
  str_homestory_N23dianying_90030301_56X2_dialog_content = "En vista de que el cantinero ha demostrado ser tan confiable, ¿puedo hacer otra solicitud?",
  str_homestory_N23dianying_90030301_56X3_dialog_content = "Tengo aquí un mensaje muy confidencial y extremadamente importante. Más tarde vendrá un intermediario a recogerlo.",
  str_homestory_N23dianying_90030301_57_dialog_content = "Espera, yo no—",
  str_homestory_N23dianying_90030301_58_dialog_content = "¡No te preocupes! Es realmente muy simple.",
  str_homestory_N23dianying_90030301_59_dialog_content = "El contacto utilizará la palabra clave \"Belleza bajo la luna\". Solo entrega la carta cuando escuches eso.",
  str_homestory_N23dianying_90030301_60_dialog_content = "Tengo otros asuntos que atender, así que me despediré.",
  str_homestory_N23dianying_90030301_60X1_dialog_content = "¡No te preocupes! Es realmente muy simple.",
  str_homestory_N23dianying_90030301_60X2_dialog_content = "El contacto utilizará la palabra clave \"Belleza bajo la luna\". Solo entrega la carta cuando escuches eso.",
  str_homestory_N23dianying_90030301_60X3_dialog_content = "Todavía tengo asuntos muy importantes que atender, así que me despediré.",
  str_homestory_N23dianying_90030301_61_dialog_content = "¡Oye! ¡No he terminado!",
  str_homestory_N23dianying_90030301_62_dialog_content = "¡Que la gente termine, Chubb!",
  str_homestory_N23dianying_90030301_63_dialog_content = "De verdad... Cada uno de estos tipos...",
  str_homestory_N23dianying_90030301_64_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  str_homestory_N23dianying_90030301_65_dialog_content = "Ahora quien es?! ¿No ven el cartel de \"CERRADO\" en la puerta?",
  str_homestory_N23dianying_90030301_66_dialog_content = "¡Alguacil llamando! Perdón por la interrupción, pero estoy aquí por la pelea que estalló aquí hace unos días.",
  str_homestory_N23dianying_90030301_66X1_dialog_content = "¡Alguacil llamando! Perdón por la interrupción, pero estoy aquí por la pelea que estalló aquí hace unos días.",
  str_homestory_N23dianying_90030301_67_dialog_content = "¿Está el dueño por aquí?",
  str_homestory_N23dianying_90030301_67X1_dialog_content = "¿Está el dueño por aquí?",
  str_homestory_N23dianying_90030301_68_dialog_content = "¿Alguacil? ¡Tiempo perfecto!",
  str_homestory_N23dianying_90030301_69_dialog_content = "Soy el cantinero aquí, y fui testigo de una discusión criminal hace un momento. Incluso me dieron una carta confidencial.",
  str_homestory_N23dianying_90030301_70_dialog_content = "¡Te diré todo lo que sé si puedes evitar que esos matones vuelvan a poner un pie aquí!",
  str_homestory_N23dianying_90030301_71_dialog_content = "¿Una carta confidencial de pandillas?",
  str_homestory_N23dianying_90030301_71X1_dialog_content = "¿Una carta confidencial de pandillas?",
  str_homestory_N23dianying_90030301_71X2_dialog_content = "Así es. Si vas tras ellos ahora, los que me dieron la carta no pueden haber ido muy lejos.",
  str_homestory_N23dianying_90030301_72_dialog_content = "Realmente has sido de mucha ayuda. Gracias por su cooperación, camarero.",
  str_homestory_N23dianying_90030301_73_dialog_content = "Una vez que sepa lo que está pasando, seré responsable de mantener este lugar seguro.",
  str_homestory_N23dianying_90030301_74_dialog_content = "Bueno, ¡adelante entonces!",
  str_homestory_N23dianying_90030301_74X1_dialog_content = "Tendré que ver lo que dice antes de poder juzgar la veracidad de su información.",
  str_homestory_N23dianying_90030301_74X2_dialog_content = "Después de todo, no puedo entender por qué te confiarían un artículo tan importante.",
  str_homestory_N23dianying_90030301_74X3_dialog_content = "Bien, sigue adelante.",
  str_homestory_N23dianying_90030301_75_dialog_content = "\"Mi queridísima doncella de la luna\"",
  str_homestory_N23dianying_90030301_76_dialog_content = "\"Aprecio tu sincero entusiasmo y admiro tu valiente franqueza\".",
  str_homestory_N23dianying_90030301_77_dialog_content = "\"Pero, la mayoría de las disculpas, no me siento de la misma manera\"...",
  str_homestory_N23dianying_90030301_78_dialog_content = "¡Es una carta de amor, Chubb!",
  str_homestory_N23dianying_90030301_79_dialog_content = "¿En que andas?",
  str_homestory_N23dianying_90030301_80_dialog_content = "¿Es esto... una carta para mí?",
  str_homestory_N23dianying_90030301_81_dialog_content = "Esto, esto es...",
  str_homestory_N23dianying_90030301_82_dialog_content = "Mi seudónimo es \"Belleza bajo la luna\"...",
  str_homestory_N23dianying_90030301_83_dialog_content = "Esto estaba dirigido a mí, ¿correcto?",
  str_homestory_N23dianying_90030301_84_dialog_content = "S-Sí.",
  str_homestory_N23dianying_90030301_85_dialog_content = "Claramente acabo de escuchar que él no pudo devolver mis sentimientos...",
  str_homestory_N23dianying_90030301_86_dialog_content = "Al final del día, todavía no podía hacer que sucediera.",
  str_homestory_N23dianying_90030301_87_dialog_content = "¡Oye! ¡¿Por qué estás tocando nuestro tocadiscos?!",
  str_homestory_N23dianying_90030301_87X1_dialog_content = "Pffffft—",
  str_homestory_N23dianying_90030301_87X2_dialog_content = "¡Hahaha!",
  str_homestory_N23dianying_90030301_87X3_dialog_content = "¡Caronte, cálmate! Cachero.",
  str_homestory_N23dianying_90030301_88_dialog_content = "Lo conocí hace un mes, bajo la luna llena.",
  str_homestory_N23dianying_90030301_89_dialog_content = "Me estaba escondiendo de unos matones en ese momento, y él me rescató.",
  str_homestory_N23dianying_90030301_90_dialog_content = "Er... ¿Por qué nos está diciendo esto?",
  str_homestory_N23dianying_90030301_91_dialog_content = "Pregunté por todas partes en la ciudad, hasta que finalmente descubrí quién era.",
  str_homestory_N23dianying_90030301_92_dialog_content = "Pero me engañaba si pensaba que un hombre de su estatura podría enamorarse de alguien como yo.",
  str_homestory_N23dianying_90030301_93_dialog_content = "¿Es por eso que eligió usar un seudónimo y escribirle una carta?",
  str_homestory_N23dianying_90030301_93X1_dialog_content = "¿Es por eso que eligió usar un seudónimo y escribirle una carta?",
  str_homestory_N23dianying_90030301_94_dialog_content = "Sí... Porque pensé que, pasara lo que pasara, no me permitiría arrepentirme.",
  str_homestory_N23dianying_90030301_95_dialog_content = "Pero he aprendido que algunos abismos son demasiado anchos para cruzarlos solo con valentía.",
  str_homestory_N23dianying_90030301_95X1_dialog_content = "Es admirable que una dama tenga tanto coraje.",
  str_homestory_N23dianying_90030301_95X2_dialog_content = "Es su pérdida rechazar a una dama tan elegante.",
  str_homestory_N23dianying_90030301_96_dialog_content = "Ciertamente puedo entender cómo te sientes, Moon Maiden.",
  str_homestory_N23dianying_90030301_97_dialog_content = "¿Es eso simpatía arrastrándose?",
  str_homestory_N23dianying_90030301_98_dialog_content = "El hecho de que tuvieras el coraje de hacer eso en primer lugar es admirable.",
  str_homestory_N23dianying_90030301_99_dialog_content = "Creo que no deberías renunciar a tu corazón tan rápido. Ayúdalo a que te entienda.",
  str_homestory_N23dianying_90030301_100_dialog_content = "No tires la toalla al primer obstáculo.",
  str_homestory_N23dianying_90030301_101_dialog_content = "Gracias... Eres la primera persona que me dice eso.",
  str_homestory_N23dianying_90030301_101X1_dialog_content = "Soy el Sheriff por aquí, así que si necesita algo en el futuro, asegúrese de venir a buscarme.",
  str_homestory_N23dianying_90030301_101X2_dialog_content = "Y... me disculpo por leer tu carta. No debería haber hecho eso.",
  str_homestory_N23dianying_90030301_101X3_dialog_content = "Creo que sólo tenías buenas intenciones.",
  str_homestory_N23dianying_90030301_101X4_dialog_content = "Gracias por su amabilidad y comprensión.",
  str_homestory_N23dianying_90030301_101X5_dialog_content = "Bueno, en cuanto a usted, Sr. Charon.",
  str_homestory_N23dianying_90030301_101X6_dialog_content = "Eh... ¿Sí?",
  str_homestory_N23dianying_90030301_101X7_dialog_content = "¿No debería ser el Sr. Cantinero?",
  str_homestory_N23dianying_90030301_101X8_dialog_content = "No puedo perdonarte de ninguna manera por entrometerte en los asuntos más personales de una joven.",
  str_homestory_N23dianying_90030301_101X9_dialog_content = "¡Tal comportamiento reprobable debe ser castigado por la ley y condenado por la moral común!",
  str_homestory_N23dianying_90030301_101X10_dialog_content = "¡...!",
  str_homestory_N23dianying_90030301_101X11_dialog_content = "¡Baja el tono, Pittman!",
  str_homestory_N23dianying_90030301_101X12_dialog_content = "¡Se está metiendo demasiado en el personaje, Chubb!",
  str_homestory_N23dianying_90030301_101X13_dialog_content = "¡Espera, espera, espera!",
  str_homestory_N23dianying_90030301_101X14_dialog_content = "¿No estamos filmando? ¿Qué dice el guión?",
  str_homestory_N23dianying_90030301_101X15_dialog_content = "¡No es que quisiera leer!",
  str_homestory_N23dianying_90030301_101X16_dialog_content = "Hmph, todavía gimiendo.",
  str_homestory_N23dianying_90030301_101X17_dialog_content = "¡Toma tu castigo!",
  str_homestory_N23dianying_90030301_101X18_dialog_content = "¡Espera!",
  str_homestory_N23dianying_90030301_101X19_dialog_content = "¡No vayas a romper mi set, O la utilería!",
  str_homestory_N23dianying_90030301_102_dialog_content = "Soy el Sheriff por aquí, así que si necesita algo en el futuro, asegúrese de venir a buscarme.",
  str_homestory_N23dianying_90030301_103_dialog_content = "De todos modos, todavía tengo cosas que hacer, así que debería irme. Nos vemos.",
  str_homestory_N23dianying_90030301_104_dialog_content = "¡Aférrate! ¿Qué pasa con la pelea?",
  str_homestory_N23dianying_90030301_105_dialog_content = "Basado en lo que acabo de ver, no estoy satisfecho de que pueda proporcionar inteligencia confiable.",
  str_homestory_N23dianying_90030301_106_dialog_content = "Es bastante despreciable entrometerse en los asuntos más privados de una dama.",
  str_homestory_N23dianying_90030301_107_dialog_content = "Voy a evaluar y adjudicar a mí mismo. Adiós.",
  str_homestory_N23dianying_90030301_108_dialog_content = "Cómo es esto posible...",
  str_homestory_N23dianying_90030301_109_dialog_content = "Ese hombre de hace un momento, ¿era... realmente el Sheriff?",
  str_homestory_N23dianying_90030301_110_option_content = "disculparme sinceramente",
  str_homestory_N23dianying_90030301_110X1_dialog_content = "¡No se quede ahí parado, asistente! ¡Haz tu disculpa!",
  str_homestory_N23dianying_90030301_111_dialog_content = "En seguida.",
  str_homestory_N23dianying_90030301_112_dialog_content = "Me disculpo por abrir una carta personal tan importante sin permiso.",
  str_homestory_N23dianying_90030301_113_dialog_content = "Está bien. Después de todo, fue una decisión tomada en un momento crítico en beneficio de la organización.",
  str_homestory_N23dianying_90030301_114_dialog_content = "¿Organización?",
  str_homestory_N23dianying_90030301_115_dialog_content = "La carta estaba escrita en código. Sólo parecía ser una carta de amor.",
  str_homestory_N23dianying_90030301_116_dialog_content = "Si bien había un riesgo inherente al abrirlo frente al Sheriff... Parece que nos salimos con la nuestra, ya que ella no sospechaba lo más mínimo.",
  str_homestory_N23dianying_90030301_117_dialog_content = "Y Night Impression hace honor a su reputación como establecimiento de confianza.",
  str_homestory_N23dianying_90030301_118_dialog_content = "Espera, ¿quieres decir que realmente eres parte de la pandilla?",
  str_homestory_N23dianying_90030301_119_dialog_content = "¿Todo eso fue inventado en el acto?",
  str_homestory_N23dianying_90030301_120_dialog_content = "Sip.",
  str_homestory_N23dianying_90030301_121_dialog_content = "¡Guau! ¡No lo vi venir, Chubb!",
  str_homestory_N23dianying_90030301_122_dialog_content = "De todos modos... Ahora que he recuperado la carta de forma segura, debería ir a mi próxima parada en esta misión.",
  str_homestory_N23dianying_90030301_123_dialog_content = "Nos vemos, Sr. Cantinero.",
  str_homestory_N23dianying_90030301_124_dialog_content = "...",
  str_homestory_N23dianying_90030301_125_dialog_content = "¡¿Lo que acaba de suceder?!",
  str_homestory_N23dianying_90030301_126_option_content = "Aconséjale que se rinda",
  str_homestory_N23dianying_90030301_126X1_dialog_content = "Vamos, asistente, ¿qué estás esperando? ¡Esta es la parte en la que debes tratar de disuadirla de continuar con la relación!",
  str_homestory_N23dianying_90030301_127_dialog_content = "Está bien...",
  str_homestory_N23dianying_90030301_128_dialog_content = "Así es, Moon Maiden... Hay algo que necesito decirte.",
  str_homestory_N23dianying_90030301_129_dialog_content = "¡Da la casualidad de que el hombre que admiras es una figura peligrosa en la pandilla!",
  str_homestory_N23dianying_90030301_130_dialog_content = "¡...!",
  str_homestory_N23dianying_90030301_131_dialog_content = "La sheriff no me creyó hace un momento, por eso te animó a que lo siguieras.",
  str_homestory_N23dianying_90030301_132_dialog_content = "Pero aun así te aconsejo que te alejes. ¿Qué pasa si él no es realmente el caballero de buen corazón que crees que es?",
  str_homestory_N23dianying_90030301_133_dialog_content = "... ¿Así que quería revelar su verdadera identidad al Sheriff?",
  str_homestory_N23dianying_90030301_134_dialog_content = "Sí. Aunque el Sheriff no me creyera, no voy a dejar de seguir las pistas.",
  str_homestory_N23dianying_90030301_135_dialog_content = "...",
  str_homestory_N23dianying_90030301_136_dialog_content = "doncella de la luna?",
  str_homestory_N23dianying_90030301_137_dialog_content = "¡¿Q-Qué vas a hacer?!",
  str_homestory_N23dianying_90030301_138_dialog_content = "Al principio pensé que el Sheriff te obligó a leer la carta.",
  str_homestory_N23dianying_90030301_139_dialog_content = "¿Ese señor cometió un error...?",
  str_homestory_N23dianying_90030301_140_dialog_content = "¿Q-Qué quieres decir?",
  str_homestory_N23dianying_90030301_141_dialog_content = "La carta estaba escrita en código. Sólo parecía ser una carta de amor.",
  str_homestory_N23dianying_90030301_142_dialog_content = "Con el fin de prevenir tal crisis.",
  str_homestory_N23dianying_90030301_143_dialog_content = "Y resulta que soy uno de los jugadores en esta misión clandestina.",
  str_homestory_N23dianying_90030301_144_dialog_content = "¡Guau! ¡No lo vi venir, Chubb!",
  str_homestory_N23dianying_90030301_145_dialog_content = "¡Aférrate! ¡¿Así que en realidad eres parte de la pandilla?!",
  str_homestory_N23dianying_90030301_146_dialog_content = "Sí... Lo siento por el subterfugio.",
  str_homestory_N23dianying_90030301_147_dialog_content = "Pero la seguridad de la organización es primordial. Entonces, por favor, Sr. Cantinero...",
  str_homestory_N23dianying_90030301_148_dialog_content = "Vas a tener que mantener la boca cerrada... para siempre.",
  str_homestory_N23dianying_90030301_149_dialog_content = "¿Q-Qué estás haciendo?",
  str_homestory_N23dianying_90030301_150_dialog_content = "¡Quedarse atrás!",
  str_homestory_N23dianying_90030301_151_option_content = "pregunta identidad",
  str_homestory_N23dianying_90030301_151X1_dialog_content = "¿Esponjó sus líneas? ¡Está cuestionando su identidad, asistente!",
  str_homestory_N23dianying_90030301_152_dialog_content = "Suena bien.",
  str_homestory_N23dianying_90030301_153_dialog_content = "Entonces, ¿la doncella de la luna?",
  str_homestory_N23dianying_90030301_154_dialog_content = "¿Sí?",
  str_homestory_N23dianying_90030301_155_dialog_content = "¿Eres realmente solo un pretendiente rechazado?",
  str_homestory_N23dianying_90030301_156_dialog_content = "...",
  str_homestory_N23dianying_90030301_157_dialog_content = "No es bueno saber demasiado, Sr. Cantinero.",
  str_homestory_N23dianying_90030301_158_dialog_content = "Pero me iré, ya que tengo la carta.",
  str_homestory_N23dianying_90030301_159_dialog_content = "Sabía que algo olía a pescado.",
  str_homestory_N23dianying_90030301_160_dialog_content = "Estoy seguro de que hay más de lo que parece en esa carta. Será mejor que tome nota de lo que dijo, mientras aún lo recuerdo.",
  str_homestory_N23dianying_90030301_161_dialog_content = "Ahora, ¿dónde está un lápiz y papel...",
  str_homestory_N23dianying_90030301_162_dialog_content = "Simplemente no podías dejarlo solo, ¿verdad?",
  str_homestory_N23dianying_90030301_163_dialog_content = "T-todavía eres—",
  str_homestory_N23dianying_90030301_164_dialog_content = "Chu! ¡Desenlace! ¡Cachero!",
  str_homestory_N23dianying_90030301_165_dialog_content = "¡Los protagonistas de las películas nunca revisan la habitación, Chubb!",
  str_homestory_N23dianying_90030301_166_dialog_content = "¿Por qué ese caballero te confiaría un artículo tan importante?",
  str_homestory_N23dianying_90030301_167_dialog_content = "¿A menos que todo fuera parte del plan?",
  str_homestory_N23dianying_90030301_168_dialog_content = "Independientemente, para evitar que surjan distracciones inesperadas. ¿Por qué no damos un pequeño paseo juntos, Sr. Cantinero?",
  str_homestory_N23dianying_90030301_169_dialog_content = "¡Esperar! ¡¿Qué estás haciendo?!",
  str_homestory_N23dianying_90030301_170_dialog_content = "¡Quedarse atrás!",
  str_homestory_N23dianying_90030301_171_dialog_content = "No lleven las cosas demasiado lejos, par de murmullos...",
  str_homestory_N23dianying_90030301_172_dialog_content = "Relájese, señor cantinero. No es nuestra intención molestarte.",
  str_homestory_N23dianying_90030301_172X1_dialog_content = "Soy buen amigo de tu jefe. No dirá nada si ocupo un poco de espacio aquí.",
  str_homestory_N23dianying_90030301_173_dialog_content = "También somos buenos amigos del jefe. Estoy seguro de que no le importará",
  str_homestory_N23dianying_90030301_174_dialog_content = "Eh... ¿Jefe?",
  str_homestory_N23dianying_90030301_175_dialog_content = "... Multa. Lo tengo.",
  str_homestory_N23dianying_90030301_176_dialog_content = "Drat. Usar a mi propio jefe para amenazarme.",
  str_homestory_N23dianying_90030301_177_dialog_content = "Este lugar no será más que un lugar frecuentado por pandillas a este ritmo.",
  str_homestory_N23dianying_90030301_178_dialog_content = "Lo siento, esto no es lo que acordamos. No hay manera de que pueda aceptar.",
  str_homestory_N23dianying_90030301_179_dialog_content = "Después de todos estos años de amistad, ¿no puedes moverte un poco?",
  str_homestory_N23dianying_90030301_179X1_dialog_content = "Has sido como un hermano para mí durante todos estos años. ¿No puedes encontrar un poco de margen de maniobra?",
  str_homestory_N23dianying_90030301_180_dialog_content = "Es solo un negocio. Todo vale en el amor y en los centros comerciales, después de todo. Son campos de batalla, no lugares para hacer amigos.",
  str_homestory_N23dianying_90030301_181_dialog_content = "Si estuvieras en mi lugar, harías exactamente lo mismo.",
  str_homestory_N23dianying_90030301_182_dialog_content = "Y realmente no piensas en mí como un verdadero amigo, a juzgar por la forma en que manipulaste el contrato la última vez.",
  str_homestory_N23dianying_90030301_183_dialog_content = "Ah, eso fue solo un pequeño malentendido.",
  str_homestory_N23dianying_90030301_184_dialog_content = "¿Vaya? ¿La última vez que interfirió en nuestro negocio también fue un malentendido?",
  str_homestory_N23dianying_90030301_185_dialog_content = "Sobre eso...",
  str_homestory_N23dianying_90030301_186_dialog_content = "¿O el tiempo anterior a eso, cuando corriste tras el olor del Sheriff?",
  str_homestory_N23dianying_90030301_187_dialog_content = "Los pocos muchachos que nos quedaron hicieron todo lo posible para proteger la mercancía del jefe, pero pagamos un precio muy alto.",
  str_homestory_N23dianying_90030301_188_dialog_content = "...",
  str_homestory_N23dianying_90030301_189_dialog_content = "Realmente no puedo comprender por qué esos muchachos todavía están dispuestos a trabajar contigo.",
  str_homestory_N23dianying_90030301_190_dialog_content = "Pero yo... He estado esperando para mostrarte lo enojado que me hiciste.",
  str_homestory_N23dianying_90030301_191_dialog_content = "¡¿Y te ATREVES a usar la palabra 'amigo' conmigo?!",
  str_homestory_N23dianying_90030301_192_dialog_content = "Ahora, ahora, si vas a pelear, llévalo a otro lado.",
  str_homestory_N23dianying_90030301_193_dialog_content = "¿Es así como funcionan las negociaciones?",
  str_homestory_N23dianying_90030301_194_dialog_content = "Déjate de pretensiones. Todo el mundo está fuera de sí mismo. No hay bien o mal aquí.",
  str_homestory_N23dianying_90030301_195_dialog_content = "¿No ha proporcionado información secreta sobre nosotros a Lionhead Gang en el pasado?",
  str_homestory_N23dianying_90030301_196_dialog_content = "Solo estamos devolviendo el favor. Equilibrar la balanza.",
  str_homestory_N23dianying_90030301_197_dialog_content = "Parece que nos guardas mucho rencor.",
  str_homestory_N23dianying_90030301_198_dialog_content = "Así que ajustemos todos los puntajes hoy, aquí y ahora.",
  str_homestory_N23dianying_90030301_199_dialog_content = "Bien por mí si eres lo suficientemente valiente como para admitir tus errores.",
  str_homestory_N23dianying_90030301_200_dialog_content = "¡No peleen aquí, ustedes dos!",
  str_homestory_N23dianying_90030301_201_dialog_content = "¡Todos simplemente se detienen! ¡Baje las armas!",
  str_homestory_N23dianying_90030301_202_dialog_content = "¡Acabo de terminar de ordenar el lugar!",
  str_homestory_N23dianying_90030301_202X1_dialog_content = "Siempre he dicho que fue un malentendido.",
  str_homestory_N23dianying_90030301_202X2_dialog_content = "No podemos escribir de la misma forma rígida que tú.",
  str_homestory_N23dianying_90030301_202X3_dialog_content = "¿Vaya? Así que la última vez, cuando robaste nuestra mercancía, ¿también fue un malentendido?",
  str_homestory_N23dianying_90030301_202X4_dialog_content = "Bueno...",
  str_homestory_N23dianying_90030301_202X5_dialog_content = "El Señor de las Sombras me hizo perseguirte a través del desierto de Reddiesel durante tres días completos y tres noches.",
  str_homestory_N23dianying_90030301_202X6_dialog_content = "Daste vueltas y vueltas, haciendo un lío con todo antes de devolvérmelo todo.",
  str_homestory_N23dianying_90030301_202X7_dialog_content = "Eso también fue un malentendido, ¿verdad?",
  str_homestory_N23dianying_90030301_202X8_dialog_content = "Oye, ¿no estamos haciendo una película?",
  str_homestory_N23dianying_90030301_202X9_dialog_content = "¿Está eligiendo ahora sacar todo esto a colación?",
  str_homestory_N23dianying_90030301_202X10_dialog_content = "¡Taki, Sinsa, por favor cálmense!",
  str_homestory_N23dianying_90030301_202A1_dialog_content = "¡Han empezado a pelear!",
  str_homestory_N23dianying_90030301_202X11_dialog_content = "Lo siento, pero no creo que podamos continuar con el rodaje.",
  str_homestory_N23dianying_90030301_202X12_dialog_content = "Apenas he estado reprimiendo mi rabia desde que vi tu rostro por primera vez en el set.",
  str_homestory_N23dianying_90030301_202X13_dialog_content = "Fascinante. Entonces, ¿qué vas a hacer al respecto? ¿Quieres tango?",
  str_homestory_N23dianying_90030301_202X14_dialog_content = "Dale.",
  str_homestory_N23dianying_90030301_202X15_dialog_content = "¡SALTE si vas a pelear! ¡No destruyas el decorado ni los accesorios!",
  str_homestory_N23dianying_90030401_1_dialog_content = "¿Se siente mal, Su Majestad?",
  str_homestory_N23dianying_90030401_2_dialog_content = "Novio dijo que no has estado comiendo bien últimamente.",
  str_homestory_N23dianying_90030401_3_dialog_content = "Están preocupados y han estado tratando de encontrar nuevas recetas para ti.",
  str_homestory_N23dianying_90030401_4_dialog_content = "Siento teneros a todos preocupados, Lola.",
  str_homestory_N23dianying_90030401_5_dialog_content = "Últimamente no tengo mucho apetito. No hay necesidad de preocupaciones.",
  str_homestory_N23dianying_90030401_6_dialog_content = "¿Por qué no probar un poco de miel que acabo de recolectar? ¡Es realmente dulce!",
  str_homestory_N23dianying_90030401_S6_dialog_content = "O, si no quieres miel, tenemos algunos platos nuevos.",
  str_homestory_N23dianying_90030401_7_dialog_content = "La miel está bien, pero el azúcar realmente no es bueno para el cuerpo.",
  str_homestory_N23dianying_90030401_8_dialog_content = "¿Eh? ¿Quién eres tú?",
  str_homestory_N23dianying_90030401_X8_dialog_content = "Niña, demasiados postres te harán obesa.",
  str_homestory_N23dianying_90030401_S8_dialog_content = "¿Su Majestad?",
  str_homestory_N23dianying_90030401_S9_dialog_content = "Soy la chef Eve, empleada por el Sr. Novio para preparar nuevos platos para ti.",
  str_homestory_N23dianying_90030401_9_dialog_content = "Mis disculpas, Su Majestad.",
  str_homestory_N23dianying_90030401_10_dialog_content = "Soy el Chef Fleur, contratado por el Sr. Novio para preparar nuevos platos para usted.",
  str_homestory_N23dianying_90030401_11_dialog_content = "Vengo del desierto de Rediesel, muy lejos de Northland.",
  str_homestory_N23dianying_90030401_12_dialog_content = "Confío en que podré traerte platos que nunca antes has probado.",
  str_homestory_N23dianying_90030401_13_dialog_content = "¿Ves esta cerveza Reddiesel? Esto es diferente a cualquier bebida que tengas aquí.",
  str_homestory_N23dianying_90030401_14_dialog_content = "Estoy seguro de que su sabor suave único excitará sus papilas gustativas.",
  str_homestory_N23dianying_90030401_X14_dialog_content = "Soy el nuevo chef empleado por ese lindo tipo Novio.",
  str_homestory_N23dianying_90030401_X15_dialog_content = "Soy del Desierto Rediesel y traje platos de los que nunca has oído hablar conmigo.",
  str_homestory_N23dianying_90030401_X16_dialog_content = "Este es el Palacio de Invierno. ¡Tenemos todos los platillos de todos los rincones del continente!",
  str_homestory_N23dianying_90030401_X17_dialog_content = "Dudo que ese sea el caso, Little Girl.",
  str_homestory_N23dianying_90030401_X18_dialog_content = "¿Ves esta cerveza Reddiesel? Esto es diferente a cualquier bebida que tengas aquí.",
  str_homestory_N23dianying_90030401_X19_dialog_content = "Es una receta exclusiva del Desierto Rediesel, y se transmite de generación en generación y no se encuentra en ningún registro.",
  str_homestory_N23dianying_90030401_S14_dialog_content = "No solo eso, también es mucho más estimulante que cualquier otra bebida.",
  str_homestory_N23dianying_90030401_S15_dialog_content = "Ultima vez, PlayerName sólo bebí unos cuantos tragos con mi hermano y...",
  str_homestory_N23dianying_90030401_S16_dialog_content = "¡E-Espera! ¡Eso no está en el guión, Eve!",
  str_homestory_N23dianying_90030401_S17_dialog_content = "¡Correcto! Entonces, ¿cuál es mi línea?",
  str_homestory_N23dianying_90030401_S18_dialog_content = "Ah, y este dragón dorado de cuatro patas.",
  str_homestory_N23dianying_90030401_15_dialog_content = "Seguro que tiene un aroma único.",
  str_homestory_N23dianying_90030401_16_dialog_content = "¡Estás bien! ¡Ya puedo olerlo desde aquí!",
  str_homestory_N23dianying_90030401_X20_dialog_content = "Este dragón dorado de cuatro patas.",
  str_homestory_N23dianying_90030401_17_dialog_content = "Y este dragón dorado de cuatro patas.",
  str_homestory_N23dianying_90030401_18_dialog_content = "Está hecho de lagartijas del desierto de la parte más profunda del desierto. La carne es firme con una piel crujiente.",
  str_homestory_N23dianying_90030401_19_dialog_content = "Es una de las comidas más famosas del Desierto de Rediesel.",
  str_homestory_N23dianying_90030401_20_dialog_content = "Suena bien.",
  str_homestory_N23dianying_90030401_21_dialog_content = "Uhm... E-Eso es diferente.",
  str_homestory_N23dianying_90030401_22_dialog_content = "En cuanto a la Desert Jewel, es el verdadero plato estrella.",
  str_homestory_N23dianying_90030401_23_dialog_content = "Está hecho de los órganos internos de los gusanos de arena, una criatura exclusiva del desierto Rediesel.",
  str_homestory_N23dianying_90030401_24_dialog_content = "¿¡Órganos internos de los gusanos de arena!?",
  str_homestory_N23dianying_90030401_25_dialog_content = "Así es. Se sazonan con rediesel y nuestro condimento único, luego se tuestan hasta que la piel esté ligeramente carbonizada.",
  str_homestory_N23dianying_90030401_26_dialog_content = "Es aromático, jugoso y muy nutritivo—",
  str_homestory_N23dianying_90030401_27_dialog_content = "¡Pará pará pará! ¡Suficiente!",
  str_homestory_N23dianying_90030401_28_dialog_content = "¡Ustedes, la gente de Rediesel Wrench, realmente comen cosas raras!",
  str_homestory_N23dianying_90030401_29_dialog_content = "¿Cómo puede soportarlo tu estómago?",
  str_homestory_N23dianying_90030401_30_dialog_content = "Calla, Lola. ¡Estamos haciendo una lectura de anuncios aquí!",
  str_homestory_N23dianying_90030401_31_dialog_content = "L-Lo siento...",
  str_homestory_N23dianying_90030401_32_dialog_content = "Seguro que suena intrigante. Tienes que enseñarnos los platos.",
  str_homestory_N23dianying_90030401_X32_dialog_content = "Seguro que suena intrigante. Tienes que enseñarnos los platos.",
  str_homestory_N23dianying_90030401_33_dialog_content = "Un placer, Su Majestad.",
  str_homestory_N23dianying_90030401_X33_dialog_content = "Rediesel gourmet, el sabor que hasta intriga a la Reina del Norte.",
  str_homestory_N23dianying_90030401_X34_dialog_content = "¡El Rediesel Foodfest ya está disponible en Rediesel Desert! ¡Por sólo cuatro veces al año!",
  str_homestory_N23dianying_90030401_X35_dialog_content = "Incluso puedes encontrarte conmigo allí si tienes suerte.",
  str_homestory_N23dianying_90030401_S33_dialog_content = "Seguro que suena intrigante. Tienes que enseñarnos los platos.",
  str_homestory_N23dianying_90030401_S34_dialog_content = "¡Un placer, Su Majestad!",
  str_homestory_N23dianying_90030401_34_dialog_content = "Rediesel gourmet, el sabor que alegra hasta a la Reina del Norte.",
  str_homestory_N23dianying_90030401_35_dialog_content = "¡El Rediesel Foodfest ya está disponible en Rediesel Desert! ¡Por sólo cuatro veces al año!",
  str_homestory_N23dianying_90030401_36_dialog_content = "¿Interesado? ¡Contacta con Odd Jobs, nuestro colaborador en Umbraton!",
  str_homestory_N23dianying_90030401_37_dialog_content = "¡Grandes descuentos para grupos y otras grandes ofertas para los primeros 100 interesados!",
  str_homestory_N23dianying_90030401_38_dialog_content = "¡No te lo pierdas!",
  str_homestory_N23dianying_90030501_1_dialog_content = "¿Está bien, señorita Vice?",
  str_homestory_N23dianying_90030501_2_dialog_content = "Oh lo siento. Me quedé en blanco por un momento allí.",
  str_homestory_N23dianying_90030501_3_dialog_content = "¿Qué estabas diciendo?",
  str_homestory_N23dianying_90030501_X1_dialog_content = "¿Director? ¿Estás bien?",
  str_homestory_N23dianying_90030501_X2_dialog_content = "¡Lo siento! Me quedé en blanco por un momento allí.",
  str_homestory_N23dianying_90030501_X3_dialog_content = "¿Qué dijiste?",
  str_homestory_N23dianying_90030501_S1_dialog_content = "¿Señor Minos? ¿Estás bien?",
  str_homestory_N23dianying_90030501_S2_dialog_content = "Oh lo siento.",
  str_homestory_N23dianying_90030501_S3_dialog_content = "¿Puedes repetir la pregunta otra vez?",
  str_homestory_N23dianying_90030501_S4_dialog_content = "Está bien. Pareces exhausto...",
  str_homestory_N23dianying_90030501_S5_dialog_content = "Lo que quería preguntar es... La última vez dijiste que te arrepentías de haber hecho esta película.",
  str_homestory_N23dianying_90030501_4_dialog_content = "Por supuesto. Lo que queria preguntar es...",
  str_homestory_N23dianying_90030501_5_dialog_content = "La última vez dijiste que te arrepentías de haber hecho esta película.",
  str_homestory_N23dianying_90030501_6_dialog_content = "¿Porqué crees?",
  str_homestory_N23dianying_90030501_X4_dialog_content = "E-Es porque nos dimos cuenta hasta que se lanzó que...",
  str_homestory_N23dianying_90030501_X5_dialog_content = "Esta película puede estar maldita.",
  str_homestory_N23dianying_90030501_S6_dialog_content = "Aunque no estoy abogando por este tipo de superstición, personalmente...",
  str_homestory_N23dianying_90030501_S7_dialog_content = "Pero el equipo, todos dicen que esta película está maldita.",
  str_homestory_N23dianying_90030501_7_dialog_content = "Porque... no fue hasta que se lanzó que nos dimos cuenta...",
  str_homestory_N23dianying_90030501_8_dialog_content = "Esta película puede estar maldita.",
  str_homestory_N23dianying_90030501_9_dialog_content = "¿Maldito?",
  str_homestory_N23dianying_90030501_10_dialog_content = "Sí. Todos los que vieron la película o participaron en su realización...",
  str_homestory_N23dianying_90030501_11_dialog_content = "Todos experimentaron cosas \"extrañas\".",
  str_homestory_N23dianying_90030501_12_dialog_content = "Hola a todos. ¡Hoy, estoy aquí para llevarte dentro de la Casa Embrujada de Andersen!",
  str_homestory_N23dianying_90030501_13_dialog_content = "Originalmente fue propiedad de Lady Astor.",
  str_homestory_N23dianying_90030501_14_dialog_content = "Gritaba cuando las velas se apagaban.",
  str_homestory_N23dianying_90030501_15_dialog_content = "Finalmente, ella pereció en un incendio.",
  str_homestory_N23dianying_90030501_16_dialog_content = "El estilo del antiguo dueño era... realmente único.",
  str_homestory_N23dianying_90030501_17_dialog_content = "Son solo estos títeres. Son un poco raros de ver.",
  str_homestory_N23dianying_90030501_18_dialog_content = "<color=#e8d9bb>*Sonido de caja de música de cuerda*</color>",
  str_homestory_N23dianying_90030501_19_dialog_content = "\"Un pequeño, dos pequeños, tres pequeños títeres♪\"",
  str_homestory_N23dianying_90030501_20_dialog_content = "A-Ahhhhhh!!!! ¡Está de vuelta!",
  str_homestory_N23dianying_90030501_X20_dialog_content = "¡He estado escuchando a esa mujer cantando esta canción todas las noches desde ese día!",
  str_homestory_N23dianying_90030501_X21_dialog_content = "¡Y he notado que su voz parece estar cada vez más cerca de mí!",
  str_homestory_N23dianying_90030501_X22_dialog_content = "Mis compañeros actores me han estado diciendo lo mismo.",
  str_homestory_N23dianying_90030501_S20_dialog_content = "Algunos actores y el personal la han estado escuchando cantar todas las noches desde entonces.",
  str_homestory_N23dianying_90030501_S21_dialog_content = "Pero personalmente no escuché nada.",
  str_homestory_N23dianying_90030501_S22_dialog_content = "¿Podría ser que estén demasiado cansados o alucinando?",
  str_homestory_N23dianying_90030501_21_dialog_content = "¡He estado escuchando a esa mujer cantando esta canción todas las noches desde ese día!",
  str_homestory_N23dianying_90030501_22_dialog_content = "¡Y he notado que su voz parece estar cada vez más cerca de mí!",
  str_homestory_N23dianying_90030501_23_dialog_content = "¿Puede ser que estés demasiado cansado o alucinando?",
  str_homestory_N23dianying_90030501_24_dialog_content = "También vi la película antes de esta entrevista.",
  str_homestory_N23dianying_90030501_25_dialog_content = "No me está pasando nada.",
  str_homestory_N23dianying_90030501_26_dialog_content = "¿Podría ser sólo una coincidencia...?",
  str_homestory_N23dianying_90030501_27_dialog_content = "<color=#e8d9bb>*Pasos acercándose*</color>",
  str_homestory_N23dianying_90030501_X27_dialog_content = "¿Qué es ese sonido?",
  str_homestory_N23dianying_90030501_S27_dialog_content = "¿Q-Qué es ese sonido?",
  str_homestory_N23dianying_90030501_S28_dialog_content = "El viento debe haber derribado algo...",
  str_homestory_N23dianying_90030501_28_dialog_content = "¿Q-Qué fue eso...?",
  str_homestory_N23dianying_90030501_29_dialog_content = "No sé. Algo parece haber sido derribado.",
  str_homestory_N23dianying_90030501_30_dialog_content = "\"Un pequeño, dos pequeños, tres pequeños títeres♪\"",
  str_homestory_N23dianying_90030501_S30_dialog_content = "A-Ahhhhhh!!!! ¡E-Esa es la canción!",
  str_homestory_N23dianying_90030501_S31_dialog_content = "Bueno.",
  str_homestory_N23dianying_90030501_31_dialog_content = "¡Ahhhhhh! ¡Esa es la canción!",
  str_homestory_N23dianying_90030501_X31_dialog_content = "¡Guaaa! ¡Eso es todo! ¡Esa es la canción!",
  str_homestory_N23dianying_90030501_32_dialog_content = "\"Cuatro pequeños, cinco pequeños, seis pequeños títeres ♪\"",
  str_homestory_N23dianying_90030501_S32_dialog_content = "¿Qué pasa?",
  str_homestory_N23dianying_90030501_S33_dialog_content = "Que no cunda el pánico. mantén la calma",
  str_homestory_N23dianying_90030501_33_dialog_content = "¿Qué pasa?",
  str_homestory_N23dianying_90030501_34_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  str_homestory_N23dianying_90030501_35_dialog_content = "¡E-La luz se apagó!",
  str_homestory_N23dianying_90030501_36_dialog_content = "\"Siete pequeños, ocho pequeños, nueve pequeños títeres♪\"",
  str_homestory_N23dianying_90030501_X36_dialog_content = "Oh, no. Es mi culpa por hacer esta película...",
  str_homestory_N23dianying_90030501_S36_dialog_content = "Tú, ¿dónde está el interruptor principal de las luces? ¡Dimelo ahora!",
  str_homestory_N23dianying_90030501_37_dialog_content = "Todo se debe a esta película... Debe haber estado maldita...",
  str_homestory_N23dianying_90030501_38_dialog_content = "\"Nueve pequeños títeres, con solo ocho pequeñas cabezas ♪\"",
  str_homestory_N23dianying_90030501_39_dialog_content = "Jejeje... ¿Te atreves a ver?",
  str_homestory_N23dianying_90030601_1_dialog_content = "Señorita Siobhan, los preparativos para la operación especial están completos. Podemos tomar medidas en cualquier momento.",
  str_homestory_N23dianying_90030601_2_dialog_content = "¡Gracias! Ahora solo estamos esperando que el Gran Mariscal haga juntos el ensayo interior del anuncio de reclutamiento...",
  str_homestory_N23dianying_90030601_X1_dialog_content = "Comandante Vivian, los preparativos para la operación especial están completos. Podemos tomar medidas en cualquier momento.",
  str_homestory_N23dianying_90030601_X2_dialog_content = "Buen trabajo. El Gran Mariscal debería estar aquí en cualquier momento. Comenzaremos el ensayo interior del anuncio de reclutamiento inmediatamente después de eso.",
  str_homestory_N23dianying_90030601_S1_dialog_content = "Comandante Barton, los preparativos para la operación especial están completos. Podemos tomar medidas en cualquier momento.",
  str_homestory_N23dianying_90030601_S2_dialog_content = "Buen trabajo. El Gran Mariscal estará aquí en cualquier momento. Comenzaremos el ensayo interior del anuncio de reclutamiento inmediatamente después de eso.",
  str_homestory_N23dianying_90030601_3_dialog_content = "Perdón por haberos hecho esperar a todos.",
  str_homestory_N23dianying_90030601_4_dialog_content = "Este es mi primer intento de un reclutamiento tan innovador. ¡Mantén tu espíritu alto y juntos le mostraremos al mundo lo valientes que son los soldados de Illumina!",
  str_homestory_N23dianying_90030601_5_dialog_content = "¡Sí señor!",
  str_homestory_N23dianying_90030601_6_dialog_content = "Espero que hoy sea el día de tu renacimiento.",
  str_homestory_N23dianying_90030601_7_dialog_content = "Tu pasado está en el pasado. Lo importante es quién serás hoy y mañana.",
  str_homestory_N23dianying_90030601_X7_dialog_content = "¿Eliges esconderte en la esquina o dar un paso al frente y pelear?",
  str_homestory_N23dianying_90030601_X8_dialog_content = "¿Estar a la altura de las expectativas, tener la confianza de la gente y responder a sus oraciones?",
  str_homestory_N23dianying_90030601_X9_dialog_content = "Ser audaces y valientes por los que amamos.",
  str_homestory_N23dianying_90030601_S7_dialog_content = "¿Dejas que los eclipses destruyan tus hogares, o te levantas y te resistes, prometiendo desgarrar su carne incluso con solo tus dientes?",
  str_homestory_N23dianying_90030601_S8_dialog_content = "Recuerda lo que te han hecho y deja que eso alimente tu ira.",
  str_homestory_N23dianying_90030601_S9_dialog_content = "Por el futuro de todos los Aurorianos, y la libertad de todos nuestros descendientes.",
  str_homestory_N23dianying_90030601_8_dialog_content = "¿Te rendirás y te acurrucarás donde estás o explorarás el mundo desconocido con tus compañeros?",
  str_homestory_N23dianying_90030601_9_dialog_content = "Explore las tierras perdidas, supere muchos obstáculos y obtenga valiosa tecnología para proteger el futuro de los aurorianos.",
  str_homestory_N23dianying_90030601_10_dialog_content = "Su compromiso total con su decisión significará experimentar agotamiento y dolor hasta cada uno de sus huesos y nervios.",
  str_homestory_N23dianying_90030601_11_dialog_content = "Rodarás por el barro mientras tu instructor te grita. Tu mente y tu cuerpo se romperán antes de ser reformados.",
  str_homestory_N23dianying_90030601_12_dialog_content = "El entrenamiento parecerá despiadado y brutal, pero todos sabemos que el respeto se gana en el filo de la espada.",
  str_homestory_N23dianying_90030601_13_dialog_content = "Las cicatrices que obtienes del entrenamiento son prueba de tu determinación.",
  str_homestory_N23dianying_90030601_14_dialog_content = "Vigilamos en la oscuridad y ahuyentamos a cualquier enemigo que se atreva a entrometerse.",
  str_homestory_N23dianying_90030601_15_dialog_content = "Nuestra voluntad férrea los quemará, ya sea que tengan garras afiladas o cuerpos enormes.",
  str_homestory_N23dianying_90030601_16_dialog_content = "Únete a nosotros y conviértete en el hueso y la carne de las legiones de Illumina.",
  str_homestory_N23dianying_90030601_17_dialog_content = "Lucha junto a tus nobles hermanos y hermanas de armas y acepta tu nuevo yo.",
  str_homestory_N23dianying_90030601_18_dialog_content = "Únete a ellos y defiende el derecho a la supervivencia de todos los aurorianos.",
  str_homestory_N23dianying_90030601_19_dialog_content = "Juntos, sois la gran muralla que se alza entre el estéril campo de batalla y vuestro cálido hogar.",
  str_homestory_N23dianying_90030601_20_dialog_content = "Yo, Reinhardt, Gran Mariscal de Illumina, mando todas las legiones de Illumina...",
  str_homestory_N23dianying_90030601_21_dialog_content = "Defiende a todos los Aurorianos a toda costa y hasta la muerte.",
  str_homestory_N23dianying_90030601_22_dialog_content = "¡Esplendor Illumina!",
  str_homestory_N23dianying_90030601_23_dialog_content = "¡Oportunidad de lotería gratis para cualquier persona que visite los centros de reclutamiento de Illumina!",
  str_homestory_N23dianying_90030601_24_dialog_content = "Los premios incluyen: la lata sazonada de Gram, la foto autografiada de Siobhan, la cama Philyshy's Comfort Expedition Bed y otros.",
  str_homestory_N23dianying_90030601_25_dialog_content = "¡Los primeros cien reclutas afortunados también recibirán un cupón de experiencia de aguas termales de Cloud Island!",
  str_homestory_N23dianying_90030601_26_dialog_content = "Ya veo. Mencionar premios para llamar la atención es un enfoque necesario.",
  str_homestory_N23dianying_90030601_27_dialog_content = "¿Vamos juntos a las aguas termales después de filmar el comercial?",
  str_homestory_N23dianying_90030601_X26_dialog_content = "¡Oportunidad de lotería gratis para cualquier persona que visite los centros de reclutamiento de Illumina!",
  str_homestory_N23dianying_90030601_X27_dialog_content = "Los premios incluyen: la lata sazonada de Gram, el vale de experiencia The Other End, las plantas suculentas de Migard y otros.",
  str_homestory_N23dianying_90030601_X28_dialog_content = "¡Los primeros cien reclutas afortunados también recibirán un Afternoon Delight Set!",
  str_homestory_N23dianying_90030601_X29_dialog_content = "¡Esperamos ver sus nombres en la lista de reclutamiento!",
  str_homestory_N23dianying_90030601_S26_dialog_content = "¡Oportunidad de lotería gratis para cualquier persona que visite los centros de reclutamiento de Illumina!",
  str_homestory_N23dianying_90030601_S27_dialog_content = "Los premios incluyen: la lata sazonada de la abuela, la piruleta detectora de minas de Vida, el bate de béisbol de Revy y otros.",
  str_homestory_N23dianying_90030601_S28_dialog_content = "¡Los primeros cien reclutas afortunados también recibirán un vale de compañía de barco Commander Barton!",
  str_homestory_N23dianying_90030601_S29_dialog_content = "¡Así es! ¡Aquí están tus posibilidades!"
}
